import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-h-001","clusterId":"H","werkstueckRef":"H.0","stufe":1,"question":"Welche Frage bringt dich in diesem Gespräch am ehesten weiter?","options":["Welche weitere Quelle könnte ich ihm zeigen, damit er den Irrtum einsieht?","Welches Bedürfnis stillt ihm diese Erklärung, und wie nehme ich es zuerst ernst?","Wie kann ich ihm nachweisen, dass die Leute im Forum die Geschichte nur erfinden?","Wie lange muss ich warten, bis er seine Meinung von selbst ändert?"],"correctIndex":1,"explanation":"Die Fakten sind schon zweimal abgeprallt, und das Gespräch dreht sich erkennbar um etwas anderes: Er erzählt von seinem Forum und seiner Entlassung, nicht von Zahlen. Das spricht dafür, dass der Glaube vor allem etwas anderes leistet, als Wissenslücken zu füllen. Eine Erklärung mit geheimem Plan ersetzt Zufall und Ohnmacht durch Absicht, und das Forum liefert Zugehörigkeit. Verschwörungsglaube wird laut Douglas, Sutton und Cichocka (2017) von epistemischen, existenziellen und sozialen Motiven angetrieben; die fünf Versprechen Sinn, Kontrolle, Einfachheit, Gemeinschaft und Selbstwert lassen sich diesen Motivgruppen zuordnen. Wer das Bedürfnis dahinter zuerst anerkennt, bleibt im Gespräch. Weitere Statistiken erreichen es nicht. Ob der Glaube es auf Dauer wirklich stillt, ist eine andere Frage: Für viele ist er eher verlockend als befriedigend. Dass die Forumsmitglieder die Geschichte nur erfinden, um zu täuschen, ist eine unbelegte Unterstellung und trifft das Bedürfnis hinter dem Glauben nicht. Auf Beruhigung zu warten, ersetzt keine Antwort auf das, was ihn antreibt.","coreRule":"⚡ Wer einen Irrglauben verstehen will, fragt zuerst, welchen Durst er stillt.","quote":"","quoteLabel":"","beleg":"Werkstück H.0 (Kernidee; Die fünf großen Versprechen; Das Härten im Feuer, Aktivierungs-Frage); Fn. gl-h-beduerfnisse (Douglas/Sutton/Cichocka 2017, S. 538)","status":"entwurf","scenario":"Dein Onkel ist überzeugt, hinter den steigenden Preisen stecke ein geheimer Plan weniger Mächtiger. Du hast ihm zweimal Statistiken zu Lieferketten und Energiepreisen gezeigt. Er winkt ab, wird gereizt und erzählt stattdessen begeistert von seinem Online-Forum, in dem sich alle „endlich verstanden“ fühlen. Seit seiner Entlassung im letzten Jahr beschäftigt ihn das Thema fast täglich.","kurz":"Wenn Zahlen zweimal abprallen und er lieber vom Forum und seiner Entlassung erzählt, leistet der Glaube vermutlich etwas anderes, als Wissenslücken zu füllen: Er ersetzt Ohnmacht durch Absicht und stiftet Zugehörigkeit. Wer das zuerst ernst nimmt, bleibt im Gespräch.","prueffrage":"Wovon redet er eigentlich begeistert, wenn die Statistiken schon abgeprallt sind?","rueckmeldung":[{"option":0,"text":"Quellen helfen dort, wo wirklich Wissen fehlt. Hier sind aber schon zwei Runden Statistiken abgeprallt, und er erzählt lieber vom Forum und seiner Entlassung. Noch mehr Belege erreichen vermutlich nicht, was ihn bindet."},{"option":2,"text":"Behauptungen im Forum zu prüfen, kann sinnvoll sein. Dass die Mitglieder alles nur erfinden, ist aber selbst unbelegt, und es berührt nicht, was ihn dort hält: das Gefühl, endlich verstanden zu werden."},{"option":3,"text":"Geduld ist im Umgang mit Angehörigen oft gut, sie bleibt hier aber ohne Antwort auf das, was ihn antreibt. Wer nur wartet, hofft, dass sich ein Bedürfnis von selbst erledigt, das gerade fast täglich neu genährt wird."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Douglas, Sutton & Cichocka (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"4","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-002","clusterId":"H","werkstueckRef":"H.0","stufe":2,"question":"Welcher Gesprächsanfang ist am wahrscheinlichsten hilfreich, wenn du das Gespräch offen halten und zugleich die Entscheidung auf eine gute Grundlage stellen willst?","scenario":"Deine Schwägerin sagt, sie lasse ihr Kind nicht impfen, weil sie Angst hat, die falsche Entscheidung zu treffen.","options":["„Deine Angst ist unbegründet. Ich zeige dir gleich die Studien, danach kannst du nur noch zustimmen.“","„Deine Sorge ist berechtigt. Ich sehe es wie du, dann müssen wir nicht weiter darüber reden.“","„Wir haben das oft besprochen. Ich schicke dir einen Überblick der Studien, dann kannst du entscheiden.“","„Du willst das Beste für dein Kind und fürchtest eine Fehlentscheidung. Lass uns die sichersten Optionen anschauen.“"],"correctIndex":3,"explanation":"Hinter der Entscheidung steht hier erkennbar ein Bedürfnis: Sicherheit und das Gefühl, keine folgenschwere Fehlentscheidung zu treffen. Wer ihre Haltung frontal angreift, wird leicht als Gegner erlebt, und Fakten, die so ankommen, verhärten meist eher die Fronten; auch ein freundlich verpackter Stapel Studien geht am eigentlichen Anliegen vorbei. Bloße Zustimmung nimmt die Angst zwar ernst, bestätigt aber die Entscheidung gegen die Impfung und beendet die Prüfung. Der Gesprächsanfang, der die Angst als Wunsch nach der richtigen Entscheidung aufgreift und zum gemeinsamen Prüfen einlädt, erkennt das Bedürfnis an, ohne dem Verzicht auf die Impfung zuzustimmen. So bleibt das Gespräch offen, und die Sache selbst kann überhaupt erst zur Sprache kommen.","coreRule":"⚡ Erst das Bedürfnis hinter einer Überzeugung anerkennen, dann gemeinsam die Sache prüfen.","beleg":"Werkstück H.0 (Anwendung & Relevanz: ‚Statt die Überzeugung anzugreifen, adressiere das Bedürfnis‘)","status":"entwurf","kurz":"Wer die Angst als Wunsch nach der richtigen Entscheidung aufgreift und zum gemeinsamen Prüfen einlädt, hält das Gespräch offen, ohne dem Verzicht auf die Impfung zuzustimmen. Frontaler Angriff oder ein bloßer Stapel Studien gehen am eigentlichen Anliegen vorbei.","prueffrage":"Wie würdest du an ihrer Stelle auf einen Satz reagieren, der deine Sorge gleich zu Beginn für unbegründet oder für erledigt erklärt?","rueckmeldung":[{"option":0,"text":"Studien gehören tatsächlich ins Gespräch. Wer die Sorge aber vom Tisch wischt und Zustimmung erzwingen will, wird leicht als Gegner erlebt, und Fakten, die so ankommen, verhärten die Fronten meist eher."},{"option":1,"text":"Die Sorge ernst zu nehmen trägt, denn dahinter steht ein echtes Bedürfnis nach Sicherheit. Zustimmen bestätigt aber die Entscheidung gegen die Impfung und beendet das Gespräch, bevor irgendetwas geprüft wurde."},{"option":2,"text":"Der Überblick ist freundlich gemeint, und Studien können helfen. Er geht aber an ihrer Angst vor einer Fehlentscheidung vorbei, und „Wir haben das oft besprochen“ klingt nach Ermüdung. Die Last der Entscheidung liegt wieder allein bei ihr."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Gagneur, A. (2020): Motivational interviewing: A powerful tool to address vaccine hesitancy. Canada Communicable Disease Report 46(4), 93–97","oeffentlich":true,"url":"https://www.canada.ca/en/public-health/services/reports-publications/canada-communicable-disease-report-ccdr/monthly-issue/2020-46/issue-4-april-2-2020/article-6-canvax-addressing-vaccine-hesitancy.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-003","clusterId":"H","werkstueckRef":"H.0","stufe":3,"question":"Du liest in einem Forum den Satz: „Wer einem Gruppenmitglied Fakten gegen dessen Überzeugung zeigt, bestärkt es damit nur noch mehr in seinem Irrtum.“ Die Debatte dreht sich im Kern um Zugehörigkeit und Identität. Was ist an dieser Behauptung am ehesten problematisch?","options":["Sie überschätzt den Effekt: Fakten verhärten in Identitätsdebatten oft die Fronten, weil sie als Angriff auf die Gruppe erlebt werden; dass sie den Irrtum tatsächlich bestärken, kommt aber nur selten vor.","Sie unterschätzt den Effekt: Fakten bestärken den Irrtum in Identitätsdebatten in aller Regel, weil die Betroffenen sie nicht verstehen und deshalb noch stärker an der Überzeugung festhalten.","Sie liegt grundsätzlich falsch: Die Identität spielt für die Wirkung einer Korrektur keine Rolle, deshalb wirken Fakten bei häufiger Wiederholung früher oder später immer.","Sie trifft nur teilweise zu: Fakten verhärten die Fronten nur bei Menschen mit geringer Bildung, bei allen anderen lösen sie den Irrtum zuverlässig auf."],"correctIndex":0,"explanation":"Wenn es im Kern um Identität und Zugehörigkeit geht, erlebt die Person Fakten oft als Angriff auf ihre Gruppe, und die Fronten verhärten sich. Daraus folgt aber nicht, dass Fakten den Irrtum aktiv verstärken: Ein solcher Backfire-Effekt ist empirisch selten. Die Behauptung verwechselt also „wirkt oft nicht“ mit „wirkt ins Gegenteil“. Fakten sind in solchen Debatten häufig nicht die richtige Währung, aber nicht per se schädlich. Wer das Bedürfnis hinter dem Glauben anspricht, hat oft bessere Chancen als mit einem weiteren Faktenstrom.","coreRule":"⚡ In Identitätsdebatten sind Fakten allein oft nicht die richtige Währung und verhärten die Fronten, bestärken den Irrtum aber nur selten (Backfire-Effekt).","beleg":"Werkstück H.0 (Anwendung & Relevanz: ‚Erkennen, dass Fakten oft nicht die richtige Währung sind‘)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Dass Fakten in Identitätsdebatten oft nichts bewirken, heißt nicht, dass sie den Irrtum verstärken. Ein solcher Backfire-Effekt ist selten. Die Behauptung verwechselt „wirkt oft nicht“ mit „wirkt ins Gegenteil“.","prueffrage":"Wie oft halten Menschen nach einer Korrektur tatsächlich stärker am Irrtum fest als vorher?","rueckmeldung":[{"option":1,"text":"In Identitätsdebatten verhärten sich die Fronten tatsächlich oft. Dass Fakten den Irrtum „in aller Regel“ bestärken, stimmt aber nicht, das ist selten. Die Verhärtung kommt auch nicht vom Nichtverstehen: Fakten wirken wie ein Angriff auf die Gruppe."},{"option":2,"text":"Dass Fakten nicht per se schaden, stimmt. Die Identität spielt aber sehr wohl eine Rolle, denn sie lässt Korrekturen oft als Angriff wirken. Und auch häufige Wiederholung löst den Irrtum nicht immer auf."},{"option":3,"text":"Dass die Wirkung von Merkmalen der Person abhängt, liegt nahe. Ausschlaggebend ist hier aber, wie stark die Überzeugung an Identität und Zugehörigkeit hängt, nicht vor allem die Bildung. Dass Fakten bei allen anderen zuverlässig wirken, geht zu weit."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Nyhan, B. (2021): Why the backfire effect does not explain the durability of political misperceptions. PNAS 118(15)","oeffentlich":true,"doi":"10.1073/pnas.1912440117","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wood, T. & Porter, E. (2019): The Elusive Backfire Effect: Mass Attitudes' Steadfast Factual Adherence. Political Behavior 41(1), 135–163","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-h-004","clusterId":"H","werkstueckRef":"H.0","stufe":4,"question":"Was ist an der Aussage deines Bekannten problematisch?","scenario":"Ein Bekannter sagt: „Bei Verschwörungsgläubigen sind Belege sinnlos. Man kann nur ihre Bedürfnisse bedienen.“ Du weißt, dass in einem großen Experiment von 2024 ein Sprachmodell in Einzelgesprächen mit gut zugeschnittenen Belegen auf die jeweiligen Überzeugungen der Teilnehmenden einging. Der Verschwörungsglaube der Teilnehmenden ließ danach nach – auch bei denen, die fest überzeugt waren.","options":["Sie ist richtig, denn nur wer eine stärkere Gemeinschaft oder eine ermächtigendere Geschichte anbietet, kann einen Glauben langfristig lösen.","Sie ist zu pauschal: Das Experiment zeigt, dass auch gut zugeschnittene Belege den Glauben lockern können, selbst bei fest Überzeugten.","Sie ist falsch, denn Bedürfnisse spielen für den Glauben keine Rolle; entscheidend ist allein, ob die Person die Belege kennt.","Sie ist unvollständig, denn Belege wirken erst, nachdem alle psychologischen Bedürfnisse der Person gestillt sind und sie ruhig geworden ist."],"correctIndex":1,"explanation":"Dass Verschwörungsglaube oft psychologische Bedürfnisse nach Sinn, Kontrolle, Gemeinschaft oder Selbstwert stillt, ist gut begründet, und dann ist es klug, ein Bedürfnis zuerst ernst zu nehmen. Daraus folgt aber nicht, dass Belege wirkungslos sind. Das widerlegt schon ein einziges gut gemachtes Gegenbeispiel: Im Experiment von 2024 lockerten gut zugeschnittene Belege den Glauben, auch bei fest Überzeugten. Die Aussage „Belege sind sinnlos“ ist ein Alles-oder-nichts-Schluss aus einer richtigen Teilbeobachtung. Auch die Behauptung, nur ein besseres Angebot wie eine stärkere Gemeinschaft oder eine ermächtigendere Geschichte könne einen Glauben lösen, widerlegt dasselbe Experiment: Ein besseres Angebot ist ein möglicher Weg, aber nicht der einzige. Genauso einseitig wäre es, Bedürfnisse zu ignorieren und allein auf die Belege zu setzen, und eine feste Reihenfolge („erst alle Bedürfnisse erfüllen, dann Belege“) ist durch nichts belegt.","coreRule":"⚡ Bedürfnisse ernst nehmen, aber Belege nicht pauschal für wirkungslos erklären: Ein einziges gut belegtes Gegenbeispiel genügt gegen „nie“ und „sinnlos“.","beleg":"Werkstück H.0 (Anwendung & Relevanz: ‚Ein besseres Angebot machen‘; Verweis auf Anhang VII.1; keine Fußnote für diese Aussage)","status":"entwurf","kurz":"Aus der richtigen Teilbeobachtung, dass Glaube oft Bedürfnisse stillt, folgt nicht, dass Belege nie wirken. Das Experiment von 2024 zeigt das Gegenteil: Zugeschnittene Belege lockerten den Glauben, selbst bei fest Überzeugten.","prueffrage":"Wer nahm am Experiment von 2024 teil, und was geschah mit dem Glauben der Teilnehmenden nach den Gesprächen?","rueckmeldung":[{"option":0,"text":"Gemeinschaft und eine ermächtigende Geschichte können ein Weg sein, aber nicht der einzige: Im Experiment lockerten schon gut zugeschnittene Belege den Glauben. Deshalb ist auch die Aussage des Bekannten nicht richtig, sondern zu pauschal."},{"option":2,"text":"Dass Belege wirken können, stimmt, doch die Aussage kippt ins andere Extrem. Bedürfnisse nach Sinn, Kontrolle oder Gemeinschaft spielen oft eine Rolle, und es ist klug, sie ernst zu nehmen. Allein auf Belege zu setzen, wäre ebenso einseitig."},{"option":3,"text":"Bedürfnisse ernst zu nehmen ist oft sinnvoll. Eine feste Reihenfolge, bei der zuerst alle gestillt sein müssen, ist aber durch nichts belegt. Im Experiment wirkten die Belege schon in den Gesprächen, auch bei fest Überzeugten."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Douglas, Sutton & Cichocka (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"doi","kurz":"Costello, Pennycook & Rand (2024): Durably reducing conspiracy beliefs through dialogues with AI. Science 385(6714), eadq1814","oeffentlich":false,"doi":"10.1126/science.adq1814","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-h-005","clusterId":"H","werkstueckRef":"H.0.1","stufe":1,"question":"Welche Deutung des Ergebnisses ist angemessen, und wie sicher darfst du dir dabei sein?","options":["Der Gedanke an den eigenen Tod verstärkt das Bedürfnis, die eigene Weltanschauung zu verteidigen. Das wäre eine mögliche Deutung, aber bei 22 Personen und gescheiterten Wiederholungen verwandter Befunde nur eine vorläufige Vermutung.","Der Gedanke an den eigenen Tod macht Menschen grundsätzlich härter. Der große Unterschied von 50 zu 455 Dollar zeigt demnach, dass dies bei jeder Todeserinnerung gilt, auch wenn die Stichprobe klein ist.","Die Richter wollten dem Versuchsleiter gefallen. Das wäre eine mögliche Deutung, aber da sie plausibel klingt, muss keine andere Erklärung mehr geprüft werden.","Der Unterschied ist reiner Zufall. Das wäre eine mögliche Deutung, aber da die Stichprobe klein ist, zeigt dies, dass der Todesgedanke keinerlei Einfluss auf Urteile hat."],"correctIndex":0,"explanation":"Ein auffälliger Unterschied zwischen zwei Gruppen verlangt zwei Prüfungen: Welche Erklärung passt zu den Daten, und wie belastbar sind die Daten selbst? Dass die Todeserinnerung das Bedürfnis weckt, die eigene Weltanschauung zu verteidigen, ist eine naheliegende Deutung, denn die mutmaßliche Prostituierte verstieß gegen die Normen dieser Weltanschauung. Bei nur 22 Richtern und gescheiterten Wiederholungsversuchen zu verwandten Todeserinnerungs-Befunden (das Richter-Experiment selbst wurde nicht wiederholt) bleibt es aber eine vorläufige Vermutung und keine gesicherte Tatsache. Die anderen Antworten schießen über das Ziel hinaus: Sie verallgemeinern aus einem einzelnen Experiment auf alle Menschen oder erklären die Deutung für endgültig geklärt oder widerlegt. Weder ein großer Unterschied noch eine kleine Stichprobe rechtfertigt solche Gewissheit.","coreRule":"⚡ Passende Erklärung nennen, Gewissheit an der Datenlage messen: Kleine Stichprobe plus gescheiterte Wiederholungen heißt vorläufig.","beleg":"Werkstück H.0.1 (Kernidee: zwei Hauptstrategien)","status":"entwurf","scenario":"In einem Experiment bekommen Richter vor ihrem Urteil zwei Fragen zum eigenen Tod. Anschließend setzen sie für eine mutmaßliche Prostituierte eine durchschnittliche Kaution von 455 Dollar fest. Die Kontrollgruppe, die diese Fragen nicht bekommen hat, setzt im Schnitt 50 Dollar fest. Das Experiment umfasste 22 Richter; mehrere große Wiederholungsversuche zu verwandten Befunden sind seither gescheitert.","kurz":"Die Deutung, dass der Todesgedanke das Verteidigen der eigenen Weltanschauung verstärkt, passt zu den Daten, bleibt bei 22 Richtern und gescheiterten Wiederholungen verwandter Befunde aber eine vorläufige Vermutung. Der Fehler wäre, sie für gesichert oder für erledigt zu halten.","prueffrage":"Wie viele Personen liegen den Zahlen zugrunde, und hat jemand das Experiment später mit anderen Teilnehmern wiederholt?","rueckmeldung":[{"option":1,"text":"Der Abstand von 50 zu 455 Dollar ist tatsächlich auffällig. Ein einzelnes Experiment mit 22 Richtern trägt aber keine Regel für alle Menschen und jede Todeserinnerung, auch ein großer Unterschied verbürgt keine Verallgemeinerung."},{"option":2,"text":"Dass Versuchsteilnehmer dem Versuchsleiter gefallen wollen, kommt tatsächlich vor. Dass eine Erklärung plausibel klingt, macht sie aber noch nicht wahr, und andere Deutungen bleiben weiter zu prüfen."},{"option":3,"text":"Bei 22 Richtern und gescheiterten Wiederholungen verwandter Befunde ist Zufall eine ernste Möglichkeit. Eine kleine Stichprobe macht den Befund aber nur unsicher und widerlegt nichts: Aus „nicht belastbar“ folgt nicht „kein Einfluss“."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"literatur","kurz":"Rosenblatt, Greenberg, Solomon, Pyszczynski & Lyon (1989): Evidence for terror management theory I. Journal of Personality and Social Psychology 57(4), 681–690","oeffentlich":false},{"typ":"doi","kurz":"Klein, R. A. u. a. (2022): Many Labs 4: Failure to Replicate Mortality Salience Effect With and Without Original Author Involvement. Collabra: Psychology 8(1), 35271","oeffentlich":true,"doi":"10.1525/collabra.35271","abruf":"2026-10-12"},{"typ":"doi","kurz":"Treger, Benau & Timko (2023): Not so terrifying after all? PLOS ONE 18(5), e0285267","oeffentlich":true,"doi":"10.1371/journal.pone.0285267","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-h-006","clusterId":"H","werkstueckRef":"H.0.1","stufe":2,"question":"Welche Erklärung für seinen Sog zum Mythos passt am besten zu allem, was du über ihn weißt, und lässt sich gut prüfen?","scenario":"Ein Bekannter hat kurz nacheinander seinen Job verloren und eine schwere Krankheit durchgemacht. Seitdem erzählt er begeistert, er gehöre zu den „Erwachten“, die einen verborgenen Plan durchschauen und gegen ihn kämpfen. Eine Freundin vermutet, er habe einfach zu viel Zeit und zu wenig zu tun. Ein anderer meint: „Der war schon immer leichtgläubig.“ Du willst verstehen, was ihn wirklich anzieht.","options":["Der Mythos füllt weggebrochene Stützen auf einmal: Er stiftet Sinn statt Chaos, gibt ihm als „Wissendem“ eine wichtige Rolle und verbindet ihn mit einer Sache, die größer ist als er selbst.","Der Mythos lenkt ihn vor allem ab: Die Beschäftigung mit dem Plan übertönt belastende Gedanken, ohne ihm eine Rolle oder ein Weltbild zu geben, das ihn dauerhaft trägt.","Der Mythos bestätigt sein angeschlagenes Selbstbild, indem er ihn als Opfer mächtiger Hintergrundkräfte zeigt, gegen die er persönlich nichts tun kann und darf.","Der Mythos nimmt ihm Verantwortung ab: Wenn alles geplant ist, muss er sein eigenes Leben nicht mehr gestalten."],"correctIndex":0,"explanation":"Die Erklärung muss zu dem passen, was der Mythos ihm bietet, und zu dem, was bei ihm gerade zusammengebrochen ist. Jobverlust und Krankheit sind typische Phasen existenzieller Unsicherheit, in denen das bisherige „Terror-Management-System“ (die Stützen, die Sinn und Selbstwert tragen) zusammenbricht. Der Mythos ersetzt gleich mehrere Stützen auf einmal: Er macht aus einer chaotischen, bedeutungslosen Welt eine geordnete, in der alles einen Plan hat (Sinn). Er macht aus einem Menschen, dem Dinge zustoßen, einen „Erwachten“ mit heldenhafter Rolle (Selbstwert). Und er lässt ihn für „die Wahrheit“ oder eine bessere Welt kämpfen, also für etwas, das größer ist als er selbst (symbolische Unsterblichkeit). Die anderen Optionen nennen diese drei Elemente nicht zusammen: Bloße Ablenkung, ein Opferbild oder die Abgabe von Verantwortung erklären weder seine heldenhafte Rolle noch den Kampf für etwas Größeres. Eine Einschränkung gehört dazu: Ob unbewusste Todesangst dahintersteckt, ist empirisch umstritten, denn große Wiederholungsstudien dazu sind gescheitert. Als Erklärung des Motivs „Sinn, Selbstwert, Zugehörigkeit zu etwas Größerem nach dem Zusammenbruch der bisherigen Stützen“ trägt die Überlegung aber auch ohne diese Zusatzannahme. Das ist eine Hypothese, die du im Gespräch prüfen kannst, kein Urteil über ihn.","coreRule":"⚡ Frag bei einer Überzeugung: Was bietet sie, und was ist gerade weggebrochen? Wer Sinn, Rolle und Größeres zugleich verspricht, lockt am stärksten.","beleg":"Werkstück H.0.1 (Anwendung & Relevanz: Verschwörungsmythos, Anfälligkeit); Fn. gl-h-1 (Rosenblatt u. a. 1989; Transparenzhinweis zu Klein u. a. 2022, Many Labs 4)","status":"entwurf","kurz":"Nach Jobverlust und Krankheit fehlen ihm mehrere Stützen zugleich. Der Mythos liefert Sinn, eine heldenhafte Rolle und eine größere Sache auf einmal; Ablenkung, Opferrolle oder Abgabe von Verantwortung erklären weder seine Heldenrolle noch seinen Kampf.","prueffrage":"Was erzählt er selbst, wenn er begeistert vom „Erwachtsein“ spricht, und was hat er seit Jobverlust und Krankheit verloren?","rueckmeldung":[{"option":1,"text":"Dass die Beschäftigung mit dem Plan Grübeln übertönt, kann sein. Warum er so begeistert erzählt und sich als Kämpfer sieht, bleibt damit offen, denn der Mythos gibt ihm offenbar durchaus eine Rolle und ein Weltbild."},{"option":2,"text":"Jobverlust und Krankheit können das Selbstbild tatsächlich angeschlagen haben. Er beschreibt sich aber als „Erwachten“, der kämpft, nicht als ohnmächtiges Opfer. Seine Heldenrolle erklärt diese Deutung nicht."},{"option":3,"text":"Ein Plan hinter allem kann entlasten, das macht diese Deutung nachvollziehbar. Er kämpft aber aktiv gegen den Plan und übernimmt eine anspruchsvolle Rolle, das passt schlecht zu einem Rückzug aus der Gestaltung seines Lebens."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Douglas, Sutton & Cichocka (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"doi","kurz":"Treger, Benau & Timko (2023): Not so terrifying after all? PLOS ONE 18(5), e0285267","oeffentlich":true,"doi":"10.1371/journal.pone.0285267","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Ohnmacht, Bedrohung, Unsicherheit als Treiber)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"4","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-h-007","clusterId":"H","werkstueckRef":"H.0.1","stufe":3,"question":"Wie solltest du die Behauptung deiner Freundin am besten einschätzen?","scenario":"Eine Freundin sagt: „Das Richter-Experiment mit 455 statt 50 Dollar Kaution beweist doch, dass Todesangst Menschen härter urteilen lässt.“ Du weißt: Der Befund stammt aus einer Studie von 1989 mit 22 Richtern. Seither sind mehrere große Wiederholungsversuche zur Todeserinnerung gescheitert, und ein anderer klassischer Befund desselben Forschungsfelds ließ sich in einer großen Wiederholung unter keiner Bedingung bestätigen. Das Richter-Experiment selbst wurde bisher nicht groß wiederholt.","options":["Als Hinweis, aber nicht als Beweis: Die Stichprobe war klein, verwandte Befunde ließen sich nicht wiederholen.","Als gesicherten Beweis: Der Unterschied von 50 zu 455 Dollar ist so groß, dass Zufall praktisch ausgeschlossen ist.","Als widerlegt: Verwandte Befunde ließen sich nicht wiederholen, also muss dieses Experiment falsch sein.","Als wertlos: Eine einzelne Studie mit Richtern kann grundsätzlich nichts über menschliches Urteilen aussagen."],"correctIndex":0,"explanation":"Eine Studie mit nur 22 Richtern ist klein, ihr Ergebnis taugt deshalb nicht als Beweis. Dazu kommt, dass mehrere große Wiederholungsversuche zur Todeserinnerung gescheitert sind. In der großen Replikation „Many Labs 4“ (Klein u. a. 2022) ließ sich ein anderer klassischer Befund desselben Forschungsfelds unter keiner Bedingung bestätigen; das Richter-Experiment von 1989 selbst wurde dort nicht wiederholt. Es gilt heute nicht mehr als unangefochten gesichert. Ein gescheiterter Befund aus demselben Forschungsfeld ist ein Warnsignal, aber kein Gegenbeweis für diese eine Studie. Angemessen ist ein vorsichtiges Urteil: ein Hinweis, der geprüft werden müsste, weder ein Beweis noch einfach Unsinn.","coreRule":"⚡ Eine kleine Einzelstudie ist ein Hinweis, kein Beweis: Erst Wiederholungen entscheiden, und ein Warnsignal aus dem Umfeld ist noch keine Widerlegung.","beleg":"Werkstück H.0.1 (Der Richter und das Kruzifix); Fn. gl-h-1 (Rosenblatt u. a. 1989, JPSP 57(4), S. 681–690, Exp. 1 S. 682; Klein u. a. 2022, Collabra 8(1))","status":"entwurf","kurz":"Eine Studie mit 22 Richtern kann nichts beweisen, und gescheiterte Wiederholungen im Feld mahnen zur Vorsicht. Sie widerlegen das Experiment aber nicht: Es bleibt ein Hinweis, der erst geprüft werden müsste.","prueffrage":"Wie oft und in welcher Größe wurde dieser Befund seit 1989 unabhängig nachgeprüft?","rueckmeldung":[{"option":1,"text":"Ein Unterschied von 50 zu 455 Dollar wirkt eindrucksvoll. Bei nur 22 Richtern kann aber auch ein großer Abstand zufällig entstehen, und ein einzelnes Ergebnis ist ohnehin noch kein Beweis."},{"option":2,"text":"Dass verwandte Befunde scheiterten, ist ein ernstes Warnsignal. Dieses Experiment selbst wurde aber nie groß wiederholt, und ein Scheitern anderswo ersetzt nicht die Prüfung genau dieser Studie."},{"option":3,"text":"Eine einzelne Studie mit einer besonderen Gruppe wie Richtern lässt sich tatsächlich nur vorsichtig verallgemeinern. „Grundsätzlich nichts“ geht aber zu weit: Sie bleibt ein Hinweis, der sich prüfen ließe."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klein, R. A. u. a. (2022): Many Labs 4: Failure to Replicate Mortality Salience Effect With and Without Original Author Involvement. Collabra: Psychology 8(1), 35271","oeffentlich":true,"doi":"10.1525/collabra.35271","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rosenblatt, Greenberg, Solomon, Pyszczynski & Lyon (1989): Evidence for terror management theory I. Journal of Personality and Social Psychology 57(4), 681–690","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-h-008","clusterId":"H","werkstueckRef":"H.0.1","stufe":3,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Dass eine Überzeugung vor Angst schützt, beweist noch nicht, dass sie schädlich ist; das zeigt sich erst an ihren Folgen im Verhalten.","Eine schützende Überzeugung ist nur dann unproblematisch, wenn ihre Träger die Angst dahinter nie bewusst wahrnehmen.","Dass eine Überzeugung ein seelisches Bedürfnis erfüllt, beweist bereits, dass sie wahr ist und deshalb niemand sie kritisieren darf.","Wer aus seiner Sterblichkeit Kunst oder Forschung schafft, verschleiert damit zwangsläufig die Wirklichkeit und handelt unehrlich."],"correctIndex":0,"explanation":"Der Fehlschluss springt vom Ursprung oder Zweck einer Überzeugung auf ihren Wert. Dass etwas ein Bedürfnis erfüllt, sagt weder, dass es wahr ist, noch, dass es schädlich ist. Folgt man der Theorie, kann dieselbe Quelle Kathedralen, Forschung und Familiengründungen antreiben, aber auch Hass. Kritisch wird es dort, wo die Verteidigung der eigenen Weltanschauung wichtiger wird als Realität oder Menschlichkeit, etwa wenn man Andersdenkende verletzt oder Fakten leugnet. Ob eine Überzeugung ungesund ist, zeigt sich also an ihren Folgen, nicht an ihrer Herkunft. Die bewusste Selbstprüfung, ob die Wut vom Argument oder von der Bedrohung des eigenen Glaubenssatzes kommt, hilft, diese Grenze rechtzeitig zu bemerken.","coreRule":"⚡ Von der Herkunft einer Überzeugung auf ihren Wert zu schließen, ist ein Fehlschluss. Prüfe, was sie im Verhalten bewirkt.","beleg":"Werkstück H.0.1 (Das Adaptive Talent; Der Kipppunkt; Das Anti-Denkmuster)","status":"entwurf","scenario":"In einer Diskussion sagt jemand: „Menschen schützen sich mit festen Überzeugungen vor der Angst vor dem Tod. Also ist jede feste Überzeugung ungesund, und wer sich wie eine Pflegerin, ein Patriot oder eine Gläubige auf einen Sinn stützt, macht sich etwas vor.“","kurz":"Dass eine Überzeugung ein Bedürfnis erfüllt, sagt noch nichts darüber, ob sie schadet. Der Fehler ist der Sprung von der Herkunft auf den Wert: Ob sie ungesund ist, zeigt sich an dem, was sie im Handeln bewirkt.","prueffrage":"Was nennt der Sprecher als Grund, und was behauptet er am Ende über die Überzeugungen?","rueckmeldung":[{"option":1,"text":"Ob jemand seine Angst bemerkt, wirkt wie ein tiefes Kriterium, entscheidet aber nicht, ob eine Überzeugung schadet; das zeigen ihre Folgen, etwa verletzte Andersdenkende oder geleugnete Fakten. Bewusstes Hinsehen hilft eher, die Grenze zu bemerken."},{"option":2,"text":"Hier wird der Fehler nur umgedreht: Aus „erfüllt ein Bedürfnis“ folgt weder „schädlich“ noch „wahr“. Ob eine Überzeugung stimmt, hängt von der Wirklichkeit ab, nicht von ihrem Nutzen für die Seele, und Kritik daran bleibt möglich."},{"option":3,"text":"Hier steckt dieselbe Verallgemeinerung wie in der ursprünglichen Aussage. Kunst oder Forschung aus dem Wissen um die Sterblichkeit ist nicht schon deshalb unehrlich: Ob sie die Wirklichkeit verschleiert, zeigt sich an ihr selbst, nicht am Antrieb."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Eintrag „Genetic Fallacy“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-h-009","clusterId":"H","werkstueckRef":"H.1.1","stufe":1,"question":"Welche Haltung hilft Karim am ehesten, mit dieser Kritik produktiv umzugehen?","options":["Er sollte Gefühle konsequent ausblenden, damit nur die Logik entscheidet und kein Ärger das Urteil verzerren kann.","Er sollte den Plan sofort zurückziehen, damit die Stimmung in der Wohnung nicht leidet und der Frieden gewahrt bleibt.","Er sollte künftig keine eigenen Vorschläge mehr machen, damit er sich nie wieder für einen Irrtum rechtfertigen muss.","Er sollte sich klarmachen, dass der Plan nur eine Hypothese ist, die scheitern darf, ohne dass sein eigener Wert daran hängt."],"correctIndex":3,"explanation":"Karims Gedanke „Wenn mein Plan nichts taugt, tauge ich nichts“ verschmilzt Person und Idee. Genau dadurch wird Kritik als Angriff auf ihn selbst erlebt, und das Ziel kippt von „den besten Plan finden“ zu „mich verteidigen“. Hilfreich ist der mentale Abstand: Der Plan ist etwas, das Karim hat, nicht etwas, das er ist. Dann kann er Lenas Einwand ernsthaft prüfen, vielleicht nachbessern oder verwerfen, ohne sich selbst infrage zu stellen. Gefühle auszublenden ist weder nötig noch möglich: Karim darf sich ärgern, entscheidend ist, dass der Ärger nicht über die Prüfung des Plans entscheidet. Den Plan sofort fallen zu lassen wäre keine Prüfung, sondern Flucht vor dem Konflikt. Gar keine Vorschläge mehr zu machen löst das Problem nicht, es vermeidet nur jede Gelegenheit zu lernen.","coreRule":"⚡ Du hast deine Idee, du bist nicht deine Idee.","beleg":"Werkstück H.1.1 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Karim hat vorgeschlagen, den Hausflur der Wohngemeinschaft jede Woche im Wechsel zu putzen. Auf der Hausversammlung nimmt Lena den Plan auseinander: Bei drei Mitbewohnern in Schichtarbeit sei er unrealistisch. Karim merkt, wie ihm die Hitze ins Gesicht steigt, und denkt: „Wenn mein Plan nichts taugt, tauge ich nichts.“","kurz":"Karim kann Lenas Einwand nur ernsthaft prüfen, wenn er den Plan als Hypothese sieht, die scheitern darf. Sein Fehler ist, Idee und Person gleichzusetzen: Dann wird Kritik zum Angriff auf ihn selbst.","prueffrage":"Was genau wirft Lena dem Plan vor, und lässt sich das an den Schichtzeiten der drei Mitbewohner nachprüfen?","rueckmeldung":[{"option":0,"text":"Ärger kann ein Urteil tatsächlich färben. Ihn auszublenden ist aber weder nötig noch möglich: Karim darf sich ärgern, solange der Ärger nicht über den Plan entscheidet. Die eigentliche Schwierigkeit ist der Gedanke, sein Wert hänge am Plan."},{"option":1,"text":"Der Wunsch nach Frieden in der WG ist verständlich. Den Plan sofort fallenzulassen prüft Lenas Einwand aber gar nicht, sondern weicht dem Konflikt aus. Ob sich der Plan an die Schichten anpassen ließe, bleibt so ungeklärt."},{"option":2,"text":"Wer nichts mehr vorschlägt, muss sich nie wieder rechtfertigen, nimmt sich aber auch jede Gelegenheit zu lernen. Außerdem bleibt der Gedanke bestehen, ein Irrtum sage etwas über den eigenen Wert aus. Er wird nur nicht mehr auf die Probe gestellt."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hayes, Levin, Plumb-Vilardaga, Villatte & Pistorello (2013): Acceptance and Commitment Therapy and Contextual Behavioral Science. Behavior Therapy 44(2), 180–198 (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3635495/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-010","clusterId":"H","werkstueckRef":"H.1.1","stufe":2,"question":"Wie ist dieses Signal am sinnvollsten zu deuten?","scenario":"Du merkst mitten in einer Diskussion über Politik, wie dir heiß wird und du nur noch deine Seite verteidigen willst, statt zuzuhören.","options":["Als Zeichen besonders gründlichen Denkens: Starke Gefühle zeigen, dass dein System 2 gerade hart an der Wahrheit arbeitet und dabei nichts übersieht.","Als Alarmsignal: Deine Identität verschmilzt gerade mit deiner Idee, das schnelle, automatische Denken übernimmt, und es geht dir weniger um Wahrheit als um Selbstverteidigung.","Als Hinweis darauf, dass dein Gegenüber im Kern recht hat: Wut entsteht vor allem dann, wenn man etwas Wahres und Unbequemes über die eigene Position hört.","Als Zeichen, dass du das Thema nie wieder diskutieren solltest: Starke Überzeugung ist immer ein Merkmal von Dogmatik, der man aus dem Weg gehen muss."],"correctIndex":1,"explanation":"Wenn eine Kritik an der Idee wie ein Angriff auf die eigene Person wirkt, springt das automatische, emotionale Verteidigungssystem an. Die Logik schaltet sich dabei nicht ab, sie wechselt die Seite: Sie dient nun dazu, die eigene Identität zu schützen, nicht dazu, die Wahrheit zu finden. Dazu passt ein viel zitiertes Experiment: Bei einer Hautcreme entschied das Rechenkönnen über die richtige Antwort auf eine Vierfeldertafel, beim Waffenverbot spaltete sich die Auswertung entlang der Weltanschauung. Spätere Wiederholungen bestätigten die weltanschauliche Färbung nur teilweise, die Verstärkung durch Rechenkönnen fanden sie nicht. Hitze und Abwehr sagen also etwas über deinen inneren Zustand, nicht über die Wahrheit der Sache. Ein starkes Gefühl beweist weder gründliches Denken noch, dass das Gegenüber recht hat. Und starke Überzeugung ist an sich noch kein Grund, ein Thema zu meiden. Hilfreich ist Abstand zur eigenen Idee: Sie ist etwas, das du hast, nicht etwas, das du bist.","coreRule":"⚡ Wirst du wütend und defensiv, verteidigst du vermutlich gerade dich und nicht die Wahrheit.","beleg":"Werkstück H.1.1 (Anwendung & Relevanz: ‚In jeder hitzigen Debatte‘; Kontext & Tiefe); Fn. gl-h-motiviert (Kahan u. a. 2017, zur motivierten Verarbeitung bei politischen Themen; Wiederholungen: Persson u. a. 2021, Stagnaro u. a. 2023)","status":"entwurf","kurz":"Wenn Kritik an der Idee wie ein Angriff auf dich wirkt, übernimmt das automatische Verteidigungssystem, und die Logik dient dann dem Schutz deiner Identität, nicht der Wahrheitssuche. Wer Hitze für Gründlichkeit hält, übersieht genau das.","prueffrage":"Was weißt du über die Sache selbst jetzt mehr als vor dem Moment, in dem dir heiß wurde?","rueckmeldung":[{"option":0,"text":"Ein starkes Gefühl wirkt wie ein Beweis dafür, dass dir die Sache ernst ist und du sie durchdenkst. Hitze und Abwehr sagen aber etwas über deinen inneren Zustand, nicht über gründliches Denken: Eher verteidigst du gerade dich selbst."},{"option":2,"text":"Dass Unbequemes Abwehr auslösen kann, ist denkbar. Aus der Wut lässt sich aber nicht ablesen, ob das Gegenüber recht hat: Sie verrät etwas über deinen inneren Zustand, nicht über die Wahrheit der Sache."},{"option":3,"text":"Auf starke Überzeugung zu achten ist sinnvoll, aber sie gleich als Dogmatik zu verwerfen, geht zu weit. Überzeugung allein ist kein Grund, ein Thema zu meiden; hilfreich ist Abstand zur eigenen Idee, nicht Ausweichen."}],"familie":"selbstrechtfertigung-erkennen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Stagnaro, Tappin & Rand (2023): No association between numerical ability and politically motivated reasoning in a large US probability sample. PNAS 120(32), e2301491120","oeffentlich":true,"doi":"10.1073/pnas.2301491120","abruf":"2026-10-12"},{"typ":"doi","kurz":"Persson, Andersson, Koppel, Västfjäll & Tinghög (2021): A preregistered replication of motivated numeracy. Cognition 214, 104768","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104768","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahan, Peters, Dawson & Slovic (2017): Motivated numeracy and enlightened self-government. Behavioural Public Policy 1(1), 54–86","oeffentlich":false,"doi":"10.1017/bpp.2016.2","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-h-011","clusterId":"H","werkstueckRef":"H.1.1","stufe":4,"question":"Ein Experiment fand: Bei einem Waffenverbot spaltete sich die Auswertung einer Vierfeldertafel politisch, bei Rechenstarken sogar stärker, bei einer neutralen Hautcreme-Aufgabe dagegen nicht. Eine große vorregistrierte Wiederholung mit 3.154 Teilnehmern fand die weltanschauliche Färbung teilweise wieder, die Verstärkung durch Rechenkönnen aber nicht. Eine Forscherin will diesen Befund als Beleg dafür nutzen, dass die Logik die Seite wechselt, wenn die Identität bedroht ist. Wie belastbar ist der Befund „Rechenkönnen verstärkt die weltanschauliche Färbung“?","options":["Die weltanschauliche Färbung beim politischen Thema ist teilweise bestätigt, dass Rechenkönnen sie verstärkt, ist es nicht; der Befund trägt die Aussage nur eingeschränkt.","Die Wiederholung hat sowohl die weltanschauliche Färbung als auch deren Verstärkung durch Rechenkönnen bestätigt; der Befund trägt die Aussage vollständig.","Die Wiederholung hat gezeigt, dass die Weltanschauung bei der Auswertung gar keine Rolle spielt; der Befund trägt die Aussage nicht.","Die Wiederholung hat gezeigt, dass Rechenschwache sich stärker von ihrer Weltanschauung leiten lassen; der Befund trägt die Aussage nur für diese Gruppe."],"correctIndex":0,"explanation":"Beim Hautcreme-Beispiel schnitten die Rechenstärksten deutlich besser ab. Beim Waffenverbot wurden die Antworten politisch gespalten, bei den Rechenstärksten sogar stärker. Die große vorregistrierte Wiederholung (Persson u. a. 2021, 3.154 Teilnehmer) fand die weltanschauliche Färbung zum Teil wieder, die Verstärkung durch Rechenkönnen aber nicht. Eine zweite vorregistrierte Wiederholung mit einer repräsentativen US-Stichprobe (Stagnaro u. a. 2023, n = 2.355) fand ebenfalls keine Verstärkung durch Rechenkönnen, wohl aber um 9,3 Prozentpunkte häufiger richtige Antworten bei einem zur eigenen Politik passenden Ergebnis. Die Originalstudie ließ sich also nur teilweise wiederholen, und ein nur teilweise bestätigter Befund darf nicht als gesichert gelten. Die Kernaussage „Weltanschauung färbt die Datenauswertung“ ist besser gestützt als der Zusatz „Rechenkönnen verstärkt das“. Als Beleg für „Logik als Anwalt der Identität“ taugt er deshalb nur mit diesem Vorbehalt.","coreRule":"⚡ Ein Befund ist nur so belastbar wie seine Wiederholung: Was sich nur teilweise bestätigt, darf nur teilweise behauptet werden.","beleg":"Werkstück H.1.1 (Kontext & Tiefe); Fn. gl-h-motiviert (Kahan u. a. 2017, Behavioural Public Policy 1(1), S. 54–86; Persson u. a. 2021, Cognition 214, Art. 104768, S. 1 und 6)","status":"entwurf","scenario":"","kurz":"Wiedergefunden wurde nur die weltanschauliche Färbung, und selbst die nur zum Teil; die Verstärkung durch Rechenkönnen blieb in der großen Wiederholung aus, ebenso in einer weiteren. Ein halb bestätigter Befund taugt daher nur eingeschränkt als Beleg.","prueffrage":"Was müsste eine Wiederholung zeigen, damit man von einer vollständigen Bestätigung sprechen kann?","rueckmeldung":[{"option":1,"text":"Eine Wiederholung mit über dreitausend Teilnehmern klingt nach einer vollen Bestätigung. Sie fand aber nur die Färbung zum Teil wieder, die Verstärkung durch Rechenkönnen dagegen nicht. „Vollständig“ trägt hier nicht."},{"option":2,"text":"Dass die Verstärkung ausblieb und der Befund die Aussage nicht voll trägt, stimmt. Die weltanschauliche Färbung fand die Wiederholung aber zum Teil wieder; dass die Weltanschauung gar keine Rolle spielt, geht daher zu weit."},{"option":3,"text":"Wenn Rechenkönnen die Färbung nicht verstärkt, liegt die Umkehrung nahe. Gefunden wurde aber nur, dass die Verstärkung ausblieb, nicht, dass Rechenschwache sich stärker von ihrer Weltanschauung leiten lassen; das wäre hinzugedichtet."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Stagnaro, Tappin & Rand (2023): No association between numerical ability and politically motivated reasoning in a large US probability sample. PNAS 120(32), e2301491120","oeffentlich":true,"doi":"10.1073/pnas.2301491120","abruf":"2026-10-12"},{"typ":"doi","kurz":"Persson, Andersson, Koppel, Västfjäll & Tinghög (2021): A preregistered replication of motivated numeracy. Cognition 214, 104768","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104768","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahan, Peters, Dawson & Slovic (2017): Motivated numeracy and enlightened self-government. Behavioural Public Policy 1(1), 54–86","oeffentlich":false,"doi":"10.1017/bpp.2016.2","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-h-012","clusterId":"H","werkstueckRef":"H.1.1","stufe":3,"question":"Wie beurteilst du die Gleichsetzung deines Freundes?","scenario":"Ein Freund aus der Psychologie sagt: „Kognitive Entkopplung kenne ich von Keith Stanovich, das ist genau das, was du meinst, wenn du sagst: Meine Idee ist etwas, das ich habe, nicht etwas, das ich bin.“ Du erinnerst dich, dass Stanovich unter „cognitive decoupling“ die Fähigkeit versteht, probeweise Annahmen von der Vorstellung der wirklichen Welt getrennt zu halten und die schnelle, automatische Antwort zu übersteuern.","options":["Sie ist richtig, weil beide Begriffe dasselbe meinen: das Lösen der eigenen Identität von Überzeugungen.","Sie ist halb richtig, weil beide Begriffe Gefühl und Verstand trennen und nur die Gruppenidentität hinzukommt.","Sie ist falsch, weil derselbe Name zwei verschiedene Fähigkeiten meint: Annahmen trennen versus Selbstwert trennen.","Sie ist falsch, weil Stanovichs Begriff aus der Akzeptanz- und Commitment-Therapie stammt und dort unverändert gilt."],"correctIndex":2,"explanation":"Ein gleicher Name sagt noch nichts über eine gleiche Sache. Bei Stanovich bedeutet „cognitive decoupling“, probeweise Annahmen von der Vorstellung der wirklichen Welt getrennt zu halten und die schnelle, automatische Antwort zu übersteuern. Das ist eine Denkfähigkeit beim probeweisen Durchspielen von Annahmen. Selbstwert und Identität von den eigenen Überzeugungen zu lösen, ist etwas anderes: Es betrifft das Verhältnis zu den eigenen Ideen, nicht das Durchspielen von Annahmen. Näher kommen dem zwei Begriffe aus der Akzeptanz- und Commitment-Therapie, die „kognitive Defusion“ (Gedanken als Gedanken bemerken, statt sie wörtlich zu nehmen) und das „Selbst als Kontext“ (die Bindung an die eigene Selbsterzählung lockern). Prüfe deshalb, was mit dem Begriff tatsächlich gemeint ist.","coreRule":"⚡ Prüfe bei Fachbegriffen, ob derselbe Name dieselbe Bedeutung trägt.","beleg":"Werkstück H.1.1; Fn. gl-h-entkopplung (nach Woods 2012, Informal Logic 32(3), S. 375 f., zu Stanovich: Rationality and the Reflective Mind, 2011); Anmerkung anm-gl-h-entkopplung","status":"entwurf","kurz":"Gleiche Namen sagen noch nichts über gleiche Sachen. Stanovich meint das probeweise Durchspielen von Annahmen, getrennt von der Vorstellung der wirklichen Welt. Selbstwert von Überzeugungen zu lösen, betrifft dagegen das Verhältnis zu den eigenen Ideen.","prueffrage":"Was müsste in Stanovichs Beschreibung stehen, damit die Gleichsetzung deines Freundes stimmt?","rueckmeldung":[{"option":0,"text":"Dass beide Begriffe mit Abstand zu Gedanken zu tun haben, lässt sie ähnlich wirken. Stanovich meint aber das probeweise Durchspielen von Annahmen und das Übersteuern der schnellen Antwort, nicht die Lösung der Identität von Überzeugungen."},{"option":1,"text":"Dass die schnelle, automatische Antwort übersteuert wird, klingt nach einer Trennung von Gefühl und Verstand. Stanovichs Begriff meint aber das Trennen probeweiser Annahmen von der wirklichen Welt, und eine Gruppenidentität kommt darin gar nicht vor."},{"option":3,"text":"Die Akzeptanz- und Commitment-Therapie ist ein guter Anhaltspunkt, nur für den falschen Begriff: Stanovichs „cognitive decoupling“ stammt aus der Denkforschung. Näher am Gemeinten sind „kognitive Defusion“ und „Selbst als Kontext“ aus der Therapie."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Woods, C. (2012): Rezension zu Stanovich, Rationality and the Reflective Mind. Informal Logic 32(3), 373–380","oeffentlich":true,"doi":"10.22329/il.v32i3.3721","abruf":"2026-10-12"},{"typ":"url","kurz":"Hayes, Levin, Plumb-Vilardaga, Villatte & Pistorello (2013): Acceptance and Commitment Therapy and Contextual Behavioral Science. Behavior Therapy 44(2) (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3635495/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Evans, J. St. B. T. & Stanovich, K. E. (2013): Dual-Process Theories of Higher Cognition: Advancing the Debate. Perspectives on Psychological Science 8(3), 223–241","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-h-013","clusterId":"H","werkstueckRef":"H.1.2","stufe":1,"question":"Jemand beschreibt seinen Alltag so: „Ich korrigiere jeden falschen Kommentar, den ich sehe, und diskutiere mit jedem, der Unsinn verbreitet. Inzwischen bin ich nach den Diskussionen ständig erschöpft und wütend, und für das Gespräch mit meinem Vater, der gerade eine ärztlich empfohlene Behandlung ablehnen will, habe ich kaum noch Kraft.“ Welche Schlussfolgerung ist am besten begründet?","options":["Er sollte seine Anstrengung bei allen Diskussionen noch erhöhen, weil jede unwidersprochene Falschmeldung Irrtümer in der Öffentlichkeit festigt.","Er sollte seine begrenzte Energie nach Dringlichkeit einteilen, weil zuerst das Gespräch mit seinem Vater zählt, wo ein echter Schaden droht.","Er sollte sich aus allen Debatten über Irrtümer heraushalten, weil Widerspruch ohnehin kaum etwas bewirkt und nur Kraft kostet.","Er sollte seine Wut und Enttäuschung in Diskussionen möglichst ausblenden, weil ihn jede einzelne Debatte dann weniger Kraft kostet."],"correctIndex":1,"explanation":"Mentale und emotionale Energie ist begrenzt. Wer jeden Irrtum sofort bekämpft, hat am Ende keine Kraft mehr für die Situation, in der Nichtstun echten Schaden anrichtet, hier die drohende Ablehnung einer ärztlich empfohlenen Behandlung. Sinnvoll ist eine Triage: Wo unmittelbarer Schaden droht, lohnt sich der volle Einsatz. Wo ein Gespräch noch offen und konstruktiv wirkt, kann man vorsichtig Energie investieren. Bei aussichtslosen Streitereien spart man sie. Mehr Einsatz verschärft die Erschöpfung. Totaler Rückzug gibt auch die Situationen auf, in denen man wirklich etwas bewirken kann. Gefühle auszublenden löst das Grundproblem nicht, denn die Ressource bleibt begrenzt und wird trotzdem verbraucht.","coreRule":"⚡ Energie ist begrenzt: erst einteilen, dann kämpfen.","quote":"","quoteLabel":"","beleg":"Werkstück H.1.2 (Die Geschichte; Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Energie ist begrenzt, und wer jeden Irrtum bekämpft, hat für den Fall, in dem Nichtstun echten Schaden anrichtet, nichts mehr übrig. Sinnvoll ist, sie nach Dringlichkeit zu verteilen: zuerst das Gespräch mit dem Vater.","prueffrage":"Was geschieht in den kommenden Wochen, wenn er so weitermacht wie bisher?","rueckmeldung":[{"option":0,"text":"Unwidersprochene Falschmeldungen können Irrtümer tatsächlich festigen. Mehr Einsatz verschärft aber die Erschöpfung und lässt noch weniger Kraft für das Gespräch mit dem Vater, wo gerade echter Schaden droht."},{"option":2,"text":"Bei aussichtslosen Streitereien spart Rückzug tatsächlich Kraft. Ganz auszusteigen gibt aber auch die Situationen auf, in denen man etwas bewirken kann, etwa beim Vater. „Kaum etwas“ ist zu pauschal, es kommt auf die Lage an."},{"option":3,"text":"Kraft zu schonen ist ein nachvollziehbares Ziel. Gefühle wegzudrücken ändert aber nichts daran, dass die Energie begrenzt ist und weiter verbraucht wird; das Unterdrücken kostet selbst Kraft. Die Verteilung der Kraft bleibt ungelöst."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","thema":"Zusammenleben"},{"id":"qx-h-014","clusterId":"H","werkstueckRef":"H.1.2","stufe":2,"question":"In welcher dieser Situationen ist es am besten begründet, deine Energie voll einzusetzen, auch wenn es anstrengend wird?","scenario":"Du hast nur begrenzt Kraft für Auseinandersetzungen und musst sie einteilen. Drei Situationen stehen an: (1) Ein anonymer Kommentator unter einem Video behauptet Unsinn und beschimpft jeden, der widerspricht. (2) Ein Kollege fragt dich ehrlich, ob an einer Gesundheitsmeldung etwas dran ist, und wirkt unsicher. (3) Dein Onkel will eine ärztlich empfohlene, lebensrettende Behandlung absagen und stattdessen auf eine unbewiesene Methode setzen.","options":["Beim Kommentator, weil unwidersprochener Unsinn im Netz sonst als wahr gilt und jede Korrektur den Schaden begrenzt.","Beim Kollegen, weil ein Gespräch mit einem Unsicheren am ehesten gelingt und deshalb die wichtigste Aufgabe ist.","Beim Onkel, weil hier Nichtstun direkten Schaden anrichtet und sich der Einsatz daher lohnt.","In allen dreien gleich, weil jede unkorrigierte falsche Behauptung langfristig Schaden anrichtet und Ausnahmen die Regel aufweichen."],"correctIndex":2,"explanation":"Wer seine Kräfte einteilt, fragt: Wo richtet Nichtstun direkten, unmittelbaren Schaden an? Beim Onkel will ein naher Angehöriger eine lebensrettende Behandlung zugunsten von Pseudomedizin ablehnen. Hier schadet Untätigkeit direkt, und das rechtfertigt vollen Einsatz, auch wenn er anstrengt. Der anonyme Kommentator hat meist kein Interesse an einem echten Austausch, wer ihm antwortet, schüttet Energie in ein Fass ohne Boden. Beim unsicheren Kollegen scheint ein konstruktiver Dialog möglich, das ist eine Schlacht, die man kämpfen kann: Hier kann ein vorsichtiger, strategischer Einsatz sinnvoll sein, aber kein voller Einsatz um jeden Preis. Wer an allen Fronten gleich kämpft, verbraucht seine Kraft an Kleinem und fehlt, wenn es wirklich darauf ankommt.","coreRule":"⚡ Wo Nichtstun unmittelbaren Schaden anrichtet, lohnt der volle Einsatz.","beleg":"Werkstück H.1.2 (Kontext & Tiefe: Triage, Kategorie 1 „Die Schlachten, die man kämpfen muss“; Geschichte vom Feuerwehrmann)","status":"entwurf","kurz":"Volle Kraft lohnt sich dort, wo Untätigkeit direkten Schaden anrichtet, hier beim Onkel und seiner lebensrettenden Behandlung. Der naheliegende Fehler ist, jede falsche Behauptung gleich zu behandeln, obwohl Kraft begrenzt ist und ungleich wirkt.","prueffrage":"Was steht in jeder der drei Situationen konkret auf dem Spiel, und für wen?","rueckmeldung":[{"option":0,"text":"Unwidersprochener Unsinn kann sich tatsächlich festsetzen. Wer aber einem Kommentator antwortet, der jeden Widersprechenden beschimpft, schüttet meist Energie in ein Fass ohne Boden, und ein direkter Schaden durch Schweigen ist hier nicht erkennbar."},{"option":1,"text":"Mit einem ehrlich Fragenden ist ein Gespräch gut möglich, dort kann vorsichtiger, strategischer Einsatz sinnvoll sein. Gute Erfolgsaussichten machen die Situation aber nicht zur dringendsten: Entscheidend ist, wo Nichtstun unmittelbar schadet."},{"option":3,"text":"Gleichmäßiger Einsatz klingt konsequent, verbraucht aber die begrenzte Kraft an Kleinem, sodass sie fehlt, wenn es wirklich darauf ankommt. Gewichten heißt nicht, Ausnahmen beliebig zuzulassen, sondern den Einsatz am möglichen Schaden auszurichten."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-015","clusterId":"H","werkstueckRef":"H.1.2","stufe":2,"question":"Welches Ziel für den nächsten Besuch ist vernünftig, und warum?","scenario":"Dein Vater hat sich in einen Mythos vertieft. Zwei längere Gespräche endeten im Streit, ohne dass er sich bewegt hat. Beim nächsten Besuch überlegst du, ob du wieder diskutierst.","options":["Bei jedem Besuch ein neues Argument nachzulegen, damit der Zweifel nicht wieder einschläft und er das Thema nicht vergessen kann.","Die Beziehung zu halten und das Thema diesmal ruhen zu lassen, um das Vertrauen nicht zu gefährden.","Den Kontakt vorerst abzubrechen, bis dein Vater von sich aus Einsicht zeigt und das Thema wieder anspricht.","Ihn im nächsten Gespräch so lange mit Fakten zu konfrontieren, bis er nachgibt, weil nur ein klarer Sieg zählt."],"correctIndex":1,"explanation":"Maßstab ist, was im Familiengespräch wirklich zählt. Das Ziel ist oft nicht, die Person in einer einzigen Diskussion zu überzeugen, sondern die Beziehung zu erhalten und ein langfristiger, vertrauenswürdiger Ansprechpartner zu bleiben. Dazu gehört zu wissen, wann man ein Thema ruhen lassen muss, um die emotionale Verbindung nicht zu zerstören. Dauerndes Nachlegen von Argumenten belastet genau diese Verbindung, und ein Kontaktabbruch gibt sie auf. Auch der Versuch, den Vater durch geballte Fakten zum Nachgeben zu bringen, macht aus dem Gespräch einen Kampf ums Gewinnen und gefährdet die Beziehung.","coreRule":"⚡ In der Familie zählt zuerst die Verbindung, nicht der Sieg im Gespräch.","beleg":"Werkstück H.1.2 (Anwendung & Relevanz: ‚Bei Familiengesprächen („Mann über Bord“)‘)","status":"entwurf","kurz":"Entscheidend ist hier die Beziehung, nicht der Sieg in einer einzelnen Diskussion. Wer das Thema ruhen lässt, bleibt ein vertrauenswürdiger Ansprechpartner, während Druck oder Abbruch genau diese Verbindung gefährden.","prueffrage":"Was haben die beiden langen Gespräche an der Meinung deines Vaters bewirkt, und wie endeten sie?","rueckmeldung":[{"option":0,"text":"Der Wunsch, den Zweifel wachzuhalten, ist verständlich. Wer aber bei jedem Besuch nachlegt, belastet die Verbindung, die ein späteres Umdenken erst möglich macht. Zwei Gespräche ohne Bewegung sprechen auch nicht dafür, dass mehr vom Gleichen hilft."},{"option":2,"text":"Den Kontakt abzubrechen wirkt konsequent, gibt aber die Beziehung auf, in der dein Vater überhaupt je wieder auf das Thema zu sprechen kommen könnte. Wer fehlt, kann auch kein verlässlicher Ansprechpartner sein, falls er einmal zweifelt."},{"option":3,"text":"Fakten zu nennen ist nicht falsch. Wer aber so lange konfrontiert, bis der andere nachgibt, macht aus dem Gespräch einen Kampf ums Gewinnen, und zwei Gespräche endeten bereits im Streit. Gewinnt einer, leidet meist die Beziehung."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-016","clusterId":"H","werkstueckRef":"H.1.2","stufe":3,"question":"Was ist hier die klügste Schlussfolgerung, und warum?","scenario":"Du diskutierst seit Wochen regelmäßig online mit Leuten über Verschwörungsmythen. Du merkst: Nach den Diskussionen bist du oft erschöpft, wütend und hoffnungslos, deine Antworten werden zynischer und aggressiver, und andere Dinge in deinem Leben kommen zu kurz. Überzeugt hast du bisher niemanden.","options":["Du bist schlecht vorbereitet. Mit mehr Recherche und besseren Gegenargumenten wird jede Debatte wieder leicht und kostet keine Kraft mehr.","Die Erschöpfung zeigt, dass du dich an den schwierigsten Fronten genug anstrengst. Mit Durchhalten wird es mit der Zeit von selbst leichter.","Das Problem sind die Andersdenkenden. Am besten streichst du sie ganz aus deinem Umfeld und sprichst nur noch mit Gleichgesinnten.","Deine Kraft ist begrenzt und wird gerade verbraucht. Du solltest neu einteilen, welche Debatten sich lohnen, und aus den übrigen aussteigen."],"correctIndex":3,"explanation":"Erschöpfung, Wut, Hoffnungslosigkeit, wachsender Zynismus und vernachlässigte andere Lebensbereiche sind typische Warnzeichen für Überlastung. Mentale und emotionale Energie ist begrenzt, und wer an jeder Front kämpft, brennt aus und hat dann für die wirklich wichtigen Auseinandersetzungen keine Kraft mehr. Mehr Vorbereitung löst das Grundproblem nicht: Bei Gegenübern, die nur gewinnen wollen, ist jede investierte Energie vergeblich – wie Wasser in ein Fass ohne Boden. Erschöpfung als Beweis für Einsatz zu werten ist ein Fehlschluss: Der Aufwand sagt nichts über den Nutzen. Pauschale Abschottung ersetzt die Triage nicht: Es gibt drei Kategorien, nicht nur „kämpfen“ oder „alles meiden“. Vernünftig ist eine Triage: Muss ich diesen Kampf führen (etwa weil Untätigkeit direkten Schaden anrichtet), kann ich ihn sinnvoll führen (das Gegenüber fragt ehrlich nach) oder sollte ich ihn vermeiden (Trolle, Ideologen, reines Gewinnen-Wollen)? Dazu gehört auch, Debatten zu verlassen oder Feeds stummzuschalten.","coreRule":"⚡ Erschöpfung ist ein Signal zum Umplanen, kein Beweis für Einsatz.","beleg":"Werkstück H.1.2 (Red Flags; Die Schmiede-Übung: Das Energie-Audit; Anwendung & Relevanz)","status":"entwurf","kurz":"Erschöpfung, Wut und wachsender Zynismus sind Warnzeichen für Überlastung, denn Energie ist begrenzt. Der naheliegende Fehler ist, trotzdem überall weiterzukämpfen. Besser prüfst du, welche Debatten wirklich nötig und sinnvoll sind, und steigst aus den anderen aus.","prueffrage":"Was hat dir der bisherige Einsatz gebracht, und was hat er dich gekostet?","rueckmeldung":[{"option":0,"text":"Gute Vorbereitung hilft in manchen Gesprächen durchaus. Wer aber nur gewinnen will, nimmt auch die besten Argumente nicht auf, und die Energie verpufft wie Wasser in einem Fass ohne Boden. Mehr Recherche löst dieses Grundproblem nicht."},{"option":1,"text":"Die Anstrengung ist real, doch Aufwand sagt nichts über den Nutzen. Erschöpfung, wachsender Zynismus und vernachlässigte Lebensbereiche ohne einen einzigen Überzeugten sind Warnzeichen für Überlastung, die mit Durchhalten eher wachsen."},{"option":2,"text":"Manche Debatten zu meiden ist sinnvoll, etwa bei Trollen. Pauschal alle Andersdenkenden auszuschließen geht aber zu weit: Manche fragen ehrlich, und manchmal schadet Untätigkeit direkt. Gefragt ist eine Auswahl, kein Rückzug in die eigene Blase."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"WHO (2019): Burn-out an „occupational phenomenon“: International Classification of Diseases","oeffentlich":true,"url":"https://www.who.int/news/item/28-05-2019-burn-out-an-occupational-phenomenon-international-classification-of-diseases","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-h-017","clusterId":"H","werkstueckRef":"H.1.3","stufe":1,"question":"Was macht Jonas anders, und was ändert das für das Gespräch?","options":["Er unterstellt dem Patienten eine gute Motivation, nämlich Sorge um die eigene Gesundheit, und prüft dann die Methode selbst. So bleibt der Patient gesprächsbereit.","Er gibt dem Patienten in der Sache teilweise recht, weil sich sein Wunsch nach Heilung nicht widerlegen lässt, und zeigt ihm so, dass er ernst genommen wird.","Er schwächt seine medizinische Einschätzung ab, damit das Gespräch weniger scharf verläuft, und zeigt dem Patienten so, dass er nicht angegriffen wird.","Er verzichtet auf die Prüfung der Methode, weil die guten Absichten des Patienten wichtiger sind als die Frage nach der Wirkung, und gewinnt so sein Vertrauen."],"correctIndex":0,"explanation":"Jonas deutet das Motiv des Patienten wohlwollend (Sorge um die Gesundheit) und greift trotzdem die Idee an, nicht die Person. Wer sich verachtet fühlt, schaltet auf Verteidigung und hört nicht mehr zu; wer sich in seinen guten Absichten verstanden fühlt, ist eher bereit, Gegenargumente zu prüfen. Die Sachprüfung bleibt dabei vollständig erhalten: Wohlwollen gegenüber dem Motiv ersetzt weder die Kritik noch die Fakten. Das Prinzip ergänzt das logische Stahlmann-Argument um die Ebene der Motive; es ersetzt die sachliche Prüfung nicht.","coreRule":"⚡ Deute das Motiv wohlwollend, prüfe die Idee trotzdem hart: Barmherzigkeit gilt der Person, nicht der falschen Behauptung.","beleg":"Werkstück H.1.3 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Ein Patient will Bleichmittel trinken, weil er fest überzeugt ist, dass es ihn von einer Krankheit heilt. Ärztin Lena reagiert: „Wie kann man nur so dumm sein?“ Arzt Jonas sagt: „Du willst unbedingt gesund werden, das verstehe ich. Lass uns gemeinsam prüfen, was Bleichmittel im Körper bewirkt.“","kurz":"Jonas deutet das Motiv wohlwollend, die Sorge um die Gesundheit, und prüft trotzdem die Methode selbst. Wer sich verachtet fühlt, hört nicht mehr zu; wer sich verstanden fühlt, prüft Gegenargumente eher.","prueffrage":"Worauf zielt jede der beiden Reaktionen: auf den Patienten als Person oder auf seine Idee?","rueckmeldung":[{"option":1,"text":"Jonas nimmt den Patienten tatsächlich ernst. Er gibt ihm aber in der Sache nicht recht: Gewürdigt wird nur der Wunsch nach Heilung; ob Bleichmittel hilft, will er erst gemeinsam mit ihm prüfen."},{"option":2,"text":"Dass das Gespräch weniger scharf wird, stimmt, kommt aber nicht von einer abgeschwächten Einschätzung. Jonas bleibt in der Sache klar und prüft die Methode mit; milder ist nur sein Umgang mit dem Motiv."},{"option":3,"text":"Die guten Absichten sind ein Anknüpfungspunkt, aber kein Ersatz für die Wirkungsfrage. Jonas lässt die Prüfung nicht fallen, er schlägt sie ausdrücklich vor. Wohlwollen ersetzt weder Kritik noch Fakten."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook, Abschnitt „How to talk to a conspiracy theorist“","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"},{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-h-018","clusterId":"H","werkstueckRef":"H.1.3","stufe":2,"question":"Du willst deinen Onkel verstehen, bevor du widersprichst, ohne seine Position gutzuheißen. Von welcher Annahme gehst du dafür am besten aus?","scenario":"Im Familienchat verteidigt dein Onkel eine politische Position, die du für schädlich hältst. Du ertappst dich beim Gedanken: „Der will doch nur das Land zerstören.“ Du willst ihm trotzdem fair begegnen, ohne deine Kritik aufzugeben.","options":["Er will wohl vor allem eigene Vorteile durchsetzen, doch solange ich ihm das nicht beweisen kann, äußere ich mich besser nicht.","Er meint es sicher gut, deshalb kann seine Position kaum so schädlich sein, wie sie mir erscheint.","Er verfolgt wohl ähnliche Ziele wie ich, hält aber einen anderen Weg für richtig.","Er hat die Sache vermutlich nicht durchdacht, und mit einer klaren Erklärung lenkt er sicher ein."],"correctIndex":2,"explanation":"Wer die Position eines anderen verstehen will, deutet seine Motive zuerst im bestmöglichen Licht: gemeinsame Ziele, andere Mittel. Das ist eine plausible Annahme, und sie lässt zu, dass du die Position weiterhin für falsch und schädlich hältst. Barmherzigkeit bedeutet nicht Naivität: Wohlwollen gegenüber der Person ersetzt nicht die Beurteilung ihrer Position, und aus „er meint es gut“ folgt nicht, dass die Position harmlos ist. Wer das gleichsetzt, verzichtet auf die Prüfung. Schlechte Motive wie Eigennutz zu unterstellen, ohne es beweisen zu können, ist genau die Dämonisierung, die man vermeiden will. Die Annahme der Gedankenlosigkeit unterstellt ihm einen Mangel, statt ein nachvollziehbares Anliegen zu suchen, und entspricht damit nicht der barmherzigen Deutung.","coreRule":"⚡ Wohlwollend deuten heißt nicht, die Position gutzuheißen.","beleg":"Werkstück H.1.3 (Anwendung & Relevanz: ‚Im politischen Diskurs‘; Kipppunkt; Red Flags)","status":"entwurf","kurz":"Wer verstehen will, deutet Motive zuerst im besten Licht: gleiche Ziele, anderer Weg. So bleibt Kritik an der Position möglich. Der Fehler wäre, ihm Böses zu unterstellen oder Wohlwollen mit einem Urteil über die Sache zu verwechseln.","prueffrage":"Welche Sorgen oder Erfahrungen könnten deinen Onkel zu dieser Position gebracht haben?","rueckmeldung":[{"option":0,"text":"Nichts zu behaupten, was man nicht belegen kann, ist redlich. Doch am Anfang steht selbst eine unbelegte Unterstellung, der Eigennutz, also genau die Dämonisierung, die vermieden werden soll. Und Schweigen ersetzt das Verstehen nicht."},{"option":1,"text":"Wohlwollen gegenüber der Person ist der richtige Anfang. Aus guten Absichten folgt aber nicht, dass die Position harmlos ist. Wer das gleichsetzt, spart sich die Prüfung der Sache, und gut Gemeintes kann trotzdem schaden."},{"option":3,"text":"Hier steckt kein Vorwurf böser Absicht, wohl aber eine Unterstellung: Er habe nicht nachgedacht. Das sucht keinen nachvollziehbaren Grund bei ihm und erwartet zudem sicheres Einlenken, was keineswegs gewiss ist."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T. & Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"qx-h-019","clusterId":"H","werkstueckRef":"H.1.3","stufe":3,"question":"Was ist an dem Einwand des Freundes problematisch?","scenario":"Ein Redner schürt seit Jahren systematisch Hass gegen eine Gruppe. Du bezeichnest sein Verhalten als gefährlich. Ein Freund widerspricht: „Wir müssen barmherzig sein und von guten Absichten ausgehen.“","options":["Er unterstellt, dass wohlwollende Deutung immer gelten muss, selbst wenn wiederholtes Verhalten klar dagegen spricht.","Er verlangt, dass man dem Redner erst nach zwei längeren Gesprächen eine schlechte Absicht unterstellen darf.","Er übersieht, dass man nur mit Menschen wohlwollend umgehen sollte, deren Ziele man selbst teilt.","Er verwechselt Wohlwollen mit Zustimmung, denn wer barmherzig deutet, muss die Position des anderen dann auch übernehmen."],"correctIndex":0,"explanation":"Das Prinzip der Barmherzigkeit gilt, bis das Gegenteil bewiesen ist. Wer systematisch Hass schürt, liefert genau dieses Gegenteil: Dann ist es nicht mehr barmherzig, sondern naiv, weiter von guten Absichten auszugehen. Beurteilt werden in diesem Fall die Handlungen, nicht die vermuteten Absichten. Der Fehler des Freundes liegt also darin, eine Ausgangsannahme in eine Regel zu verwandeln, die keine Beobachtung mehr korrigieren kann.","coreRule":"⚡ Wohlwollende Deutung gilt, bis das Verhalten das Gegenteil zeigt; dann zählen die Handlungen, nicht vermutete Absichten.","quote":"Das Prinzip der Barmherzigkeit gilt, bis das Gegenteil bewiesen ist.","quoteLabel":"Merksatz:","beleg":"Werkstück H.1.3 (Der Kipppunkt)","status":"entwurf","kurz":"Barmherzige Deutung ist ein Ausgangspunkt, bis das Gegenteil sichtbar wird. Wer jahrelang Hass schürt, zeigt es durch sein Handeln. Der Freund macht aus der Ausgangsannahme eine Regel, die sich durch keine Beobachtung mehr korrigieren lässt.","prueffrage":"Was weiß man über den Redner aus seinem Handeln, und was wird über ihn nur vermutet?","rueckmeldung":[{"option":1,"text":"Eine feste Zahl an Gesprächen klingt nach einer fairen Probezeit, doch davon sagt der Freund nichts. Er verlangt guten Glauben ohne jede Grenze, obwohl jahrelange systematische Hetze längst dagegen spricht."},{"option":2,"text":"Bei Menschen mit fremden Zielen fällt Wohlwollen schwer, deshalb liegt dieser Gedanke nahe. Barmherzige Deutung gilt aber unabhängig von geteilten Zielen. Sie endet nur, wenn das Verhalten ihr klar widerspricht."},{"option":3,"text":"Wohlwollen und Zustimmung sind tatsächlich zweierlei. Genau deshalb geht dieser Vorwurf am Freund vorbei: Er verlangt keine Zustimmung, sondern hält an einer Annahme guter Absichten fest, die das Verhalten des Redners längst widerlegt hat."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-020","clusterId":"H","werkstueckRef":"H.1.3","stufe":4,"question":"Person A versteht unter Wohlwollen die wohlwollende Deutung der Aussage (dem Sprecher wahre und stimmige Überzeugungen unterstellen), Person B das Unterstellen guter Motive. Was ist an der Annahme falsch, beide meinten dasselbe?","options":["Nichts, denn wer die Aussage wohlwollend deutet, unterstellt damit automatisch auch gute Motive, und umgekehrt.","Beides ist verschieden: A betrifft die Deutung der Aussage, B die Annahme über das Motiv; das eine geht ohne das andere.","Beides ist verschieden: A meint Nachsicht gegenüber schädlichem Verhalten, B meint Nachsicht nur bei nachweislich guter Absicht.","Beides ist verschieden: A meint den Bau der stärksten Fassung eines Arguments, B meint diese Fassung nur bei gläubigen Gesprächspartnern."],"correctIndex":1,"explanation":"Wohlwollende Deutung der Aussage und wohlwollende Annahme über das Motiv sind zwei getrennte Dinge. Die sprachphilosophische Fassung des Prinzips der Nachsicht (Donald Davidson) rät, einem Sprecher wo immer plausibel wahre und in sich stimmige Überzeugungen zu unterstellen. Davon unterscheidet sich die Annahme, jemand handle aus guten Beweggründen wie Sorge oder gutem Willen. Man kann jemandes Aussage wohlwollend deuten und trotzdem seine Motive für fragwürdig halten, oder umgekehrt von guten Motiven ausgehen und die Aussage dennoch für falsch halten. Das Prinzip der intellektuellen Barmherzigkeit erweitert den Fachbegriff bewusst um die Motivebene. Wer beides gleichsetzt, verwechselt deshalb zwei Schritte, die man getrennt prüfen muss.","coreRule":"⚡ Die Aussage wohlwollend deuten und gute Motive unterstellen sind zwei verschiedene Schritte, die man getrennt prüfen kann.","beleg":"Werkstück H.1.3 (Kontext & Tiefe); Fn. gl-h-charity (Malpas, Stanford Encyclopedia of Philosophy, „Donald Davidson“, Abschn. 3.3)","status":"entwurf","scenario":"Zwei Leute streiten über die Frage, was es heißt, den Gegner wohlwollend zu behandeln. Person A sagt: „Wohlwollen heißt, dem Gegner wahre und stimmige Überzeugungen zu unterstellen.“ Person B sagt: „Wohlwollen heißt, ihm gute Motive zu unterstellen.“ Du sollst klären, ob beide dasselbe meinen.","kurz":"Aussage und Motiv sind zwei getrennte Schritte: Man kann eine Aussage wohlwollend deuten und trotzdem die Motive für fragwürdig halten, oder von guten Motiven ausgehen und die Aussage für falsch halten. Wer beides gleichsetzt, verwechselt zwei Prüfungen.","prueffrage":"Welche Wörter benutzen A und B tatsächlich, und worauf beziehen sie sich jeweils?","rueckmeldung":[{"option":0,"text":"Beides geht im Alltag oft Hand in Hand, daher wirkt es wie eine Einheit. Das eine folgt aber nicht zwingend aus dem anderen: Eine Aussage lässt sich stimmig deuten, während man die Motive anzweifelt, und umgekehrt."},{"option":2,"text":"Dass beide Positionen verschieden sind, stimmt. Die Begründung trifft aber keine von beiden: A betrifft die Deutung der Aussage, nicht Nachsicht gegenüber schädlichem Verhalten, und B nennt gute Motive, ohne einen Nachweis zur Bedingung zu machen."},{"option":3,"text":"Dass beide verschieden sind, stimmt. Doch A meint nicht den Bau der stärksten Fassung eines Arguments, und B knüpft nichts an gläubige Gesprächspartner. Der Unterschied liegt zwischen der Deutung der Aussage und der Annahme über das Motiv."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Malpas, J.: Donald Davidson. Stanford Encyclopedia of Philosophy (rev. 28.04.2023), Abschnitt 3.3","oeffentlich":true,"url":"https://plato.stanford.edu/entries/davidson/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dresner, E. (2011): The Principle of Charity and Intercultural Communication. International Journal of Communication 5, 969–982","oeffentlich":true,"url":"https://ijoc.org/index.php/ijoc/article/view/817","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-h-021","clusterId":"H","werkstueckRef":"H.1.4","stufe":1,"question":"Was ist an diesem Argument fehlerhaft?","options":["Es nimmt an, dass Logik allein eine Wahl treffen kann, obwohl ohne Gefühle Präferenzen, Werte und Dringlichkeit fehlen.","Es nimmt an, dass Emotionen das Denken stören, obwohl bei der Operation auch Intelligenz und Gedächtnis verloren gingen.","Es nimmt an, dass sich Gefühl und Verstand gegenseitig beeinflussen, obwohl beide in getrennten Hirnregionen arbeiten.","Es nimmt an, dass nüchterne Entscheidungen immer gut sind, obwohl der Mann auch bei wichtigen Fragen zu schnell entschied."],"correctIndex":0,"explanation":"Der Fallbericht widerlegt die Behauptung: Trotz intakter Intelligenz, intaktem logischem Denken und intaktem Gedächtnis konnte der Mann nicht einmal entscheiden, wie er Akten ordnen sollte. Auch bei einem Patienten mit gleichartiger Schädigung zeigte sich dasselbe Muster: Er zählte endlos Gründe für und gegen zwei Termine auf, doch ohne die emotionale Präferenz, die sagt: „Nimm einfach den!“, fand die Abwägung kein Ende. Logik kann Optionen analysieren, aber sie liefert keine Rangfolge der Ziele und kein Gefühl der Dringlichkeit. Wer Gefühle abschaltet, gewinnt deshalb keine Überlegenheit, sondern verliert Orientierung. Die Gegenoptionen behaupten Dinge, die der Fall nicht zeigt: Intelligenz und Gedächtnis blieben erhalten, der Mann entschied nicht zu schnell, sondern gar nicht, und von getrennten Hirnregionen ohne Wechselwirkung kann keine Rede sein. Der Vorbehalt: Wie genau Gefühle in die Wahl eingreifen, etwa über Körpersignale, ist wissenschaftlich umstritten. Dass Menschen ohne Gefühlsreaktion in Entscheidungen scheitern, zeigt der Fall aber deutlich.","coreRule":"⚡ Wer Gefühle abschaltet, wird nicht klüger, sondern entscheidungsunfähig: Logik analysiert die Optionen, Gefühle geben Präferenz, Richtung und Dringlichkeit.","quote":"Emotionen sind nicht der Feind der Logik, sondern ihr notwendiger Steuermann.","quoteLabel":"Merksatz:","beleg":"Werkstück H.1.4 (Der handlungsunfähige Vulkanier; Kernidee); Fn. gl-h-2 (Damasio 1994, Descartes' Error, Elliot S. 34–51, Taschenbuchausgabe 1995)","status":"entwurf","scenario":"In einer Diskussion über Entscheidungen sagt jemand: „Gefühle stören nur. Wer seine Emotionen abschaltet, entscheidet automatisch besser. Ein Mensch, der nur noch logisch denkt, hätte alle Vorteile und würde im Alltag souverän klarkommen.“\\n\\nDazu ein Fallbericht: Ein Mann verliert nach einer Operation am Stirnhirn seine Gefühlsreaktionen. Intelligenz, logisches Denken und Gedächtnis bleiben vollständig intakt. Trotzdem grübelt er einen ganzen Nachmittag darüber, ob er Akten nach Datum, Umfang oder Bedeutung ordnen soll, und verliert seine Stelle.","kurz":"Logik kann Möglichkeiten analysieren, aber keine Rangfolge der Ziele und kein Gefühl der Dringlichkeit liefern. Wer Gefühle abschaltet, gewinnt deshalb keine Überlegenheit, sondern verliert Orientierung, wie der Mann zeigt, der nicht einmal Akten ordnen konnte.","prueffrage":"Was konnte der Mann trotz intakter Intelligenz und intaktem Denken im Alltag nicht mehr leisten?","rueckmeldung":[{"option":1,"text":"Dass Gefühle nach dieser Sicht „stören“, steckt wirklich im Argument. Die Begründung passt aber nicht zum Fall: Intelligenz, logisches Denken und Gedächtnis blieben vollständig erhalten. Genau deshalb ist sein Scheitern so aufschlussreich."},{"option":2,"text":"Gefühl und Verstand beeinflussen einander nachweislich, von getrennten Regionen ohne Wechselwirkung kann keine Rede sein. Der Fall zeigt es: Ohne Gefühlsreaktionen geriet das Entscheiden ins Stocken. Das Argument hält Gefühle für verzichtbar."},{"option":3,"text":"Dass nüchtern nicht automatisch gut heißt, deutet in die richtige Richtung. Der Mann entschied aber nicht zu schnell, sondern gar nicht: Er grübelte endlos über das Ordnen der Akten. Die Begründung dreht das Muster aus dem Fall um."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation. Neuroscience and Biobehavioral Reviews 30(2), 239–271 (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","seite":"4–5 (Manuskriptzählung)","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Damasio, A. R. (1994): Descartes' Error: Emotion, Reason, and the Human Brain. New York: Putnam","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-h-022","clusterId":"H","werkstueckRef":"H.1.4","stufe":2,"question":"Welche Antwort geht auf diese Aussage am besten ein?","scenario":"Beim Grillen sagt jemand: „Man sollte immer auf sein Herz hören und nicht auf den kalten Verstand.“ Du willst weder einfach zustimmen noch die Aussage abtun, sondern sie in einen Rahmen setzen, in dem beide Seiten ihren Platz haben.","options":["Da hast du recht: Gefühle zeigen den Weg, und die Logik kann man sich bei wichtigen Entscheidungen meist sparen.","Das stimmt nur teilweise: Gefühle stören bei wichtigen Entscheidungen, deshalb sollte man sie dort möglichst ausschalten.","Das ist ein Kampf: Herz und Verstand sind Gegner, und bei wichtigen Entscheidungen gewinnt eben der Stärkere.","Beides wird gebraucht: Der Verstand analysiert die Optionen, das Gefühl gibt Richtung, und keines ersetzt das andere."],"correctIndex":3,"explanation":"Die Aussage setzt Herz und Verstand als Gegensatz, und beide Extreme scheitern. Ohne Gefühl fehlen Präferenzen, Werte und Dringlichkeit: Der Neurologe Antonio Damasio beschrieb Patienten mit einer Schädigung im unteren, mittleren Stirnhirn (ventromedialer präfrontaler Cortex), deren Intelligenz intakt war und die trotzdem an Banalitäten scheiterten; einer von ihnen, Elliot, grübelte einen ganzen Nachmittag darüber, wie er Akten ordnen sollte, ein anderer brauchte fast eine halbe Stunde für die Wahl zwischen zwei Terminen. Logik kann Optionen analysieren, aber nicht sagen, welches Ziel man anstreben soll. Ohne Prüfung dagegen kann ein einzelnes starkes Gefühl wie Angst oder Gier die Entscheidung kapern. Die tragfähige Antwort lässt daher beides gelten: Der Verstand analysiert die Optionen, das Gefühl gibt Richtung, und keines ersetzt das andere.","coreRule":"⚡ Herz und Verstand sind Partner: Der eine lenkt, der andere prüft den Weg.","beleg":"Werkstück H.1.4 (Werkbank-Frage; Kernidee; Red Flags)","status":"entwurf","kurz":"Der Verstand kann Optionen analysieren, aber nicht sagen, welches Ziel zählt; das Gefühl liefert Richtung und Dringlichkeit, braucht aber die Prüfung. Der Fehler liegt im Gegensatz selbst, denn beide Extreme scheitern.","prueffrage":"Wie lief deine letzte wichtige Entscheidung ab, und welche Rolle spielten dabei Bauchgefühl und Nachrechnen?","rueckmeldung":[{"option":0,"text":"Dass Gefühle Richtung geben, trifft zu. Wer die Logik aber meist spart, lässt ein einzelnes starkes Gefühl wie Angst oder Gier ungeprüft entscheiden. Damit wird das Extrem des Satzes nur bestätigt statt eingeordnet."},{"option":1,"text":"Starke Gefühle können Urteile verzerren, das stimmt. Ganz ohne sie fehlen aber Werte, Präferenzen und Dringlichkeit, und selbst einfache Wahlen werden zur Qual. Das ist das umgekehrte Extrem, nicht der Mittelweg."},{"option":2,"text":"Manchmal widersprechen sich Kopf und Gefühl, das stimmt. Ein Kampf mit Sieger übernimmt aber genau den Gegensatz aus dem Satz am Grill: Wer allein gewinnt, entscheidet ohne die andere Seite, und allein scheitern beide."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","seite":"4–5 (Manuskriptzählung)","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Damasio, A. R. (1994): Descartes' Error: Emotion, Reason, and the Human Brain. New York: Putnam","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-h-023","clusterId":"H","werkstueckRef":"H.1.4","stufe":3,"question":"Ein Kollege erzählt: „Als die Aktie über Nacht um 30 Prozent fiel, wurde mir ganz heiß vor Angst. Ich habe sofort alles verkauft, ohne nachzurechnen. Eine Stunde später stand sie wieder fast auf dem alten Kurs.“ Was erklärt am besten, warum sein Vorgehen zum Problem wurde?","options":["Die Angst hat sein Denken verdrängt und allein entschieden, sodass eine überstürzte, kurzsichtige Handlung ohne jede Prüfung der Fakten herauskam.","Ein Gefühl hat überhaupt in seine Entscheidung eingegriffen, und jedes Urteil mit Gefühlseinfluss ist grundsätzlich verzerrt und unvernünftig.","Er hat sich von einem negativen Gefühl leiten lassen, während positive Gefühle wie Freude das Urteil in solchen Lagen nie trüben.","Er hat überhaupt ein körperliches Signal bemerkt, und Körpersignale sind als Hinweise stets unzuverlässiger als eine ruhige Rechnung."],"correctIndex":0,"explanation":"Die Angst an sich war nicht das Problem. Gefühle geben Orientierung, Priorität und Dringlichkeit, und dass ihn der Kurssturz alarmiert hat, ist als Datenpunkt sogar nützlich. Zum Problem wurde die Lage erst, als die starke Emotion das Nachdenken komplett ersetzt hat: Er hat weder nachgerechnet noch Gründe für oder gegen den Verkauf geprüft. Dann entscheidet das Gefühl allein, und das Ergebnis sind impulsive, kurzsichtige Handlungen. Ein Denken ganz ohne Gefühl wäre dagegen nicht besser, sondern orientierungslos: Patienten mit gestörter Verbindung zwischen Gefühl und Verstand zerdenken schon einfache Terminwahlen endlos. Sinnvoll ist, das Gefühl ernst zu nehmen und dann zu prüfen, welche Fakten es stützen oder widerlegen.","coreRule":"⚡ Gefühle beraten gut, aber sie dürfen nicht allein regieren.","beleg":"Werkstück H.1.4 (Der Kipppunkt; Red Flags: emotionale Kaperung)","status":"entwurf","scenario":"","kurz":"Die Angst selbst war ein brauchbarer Alarm. Zum Problem wurde, dass sie das Nachdenken ersetzt hat: Er prüfte weder Zahlen noch Gründe, und dann entscheidet das Gefühl allein, was oft zu impulsiven, kurzsichtigen Handlungen führt.","prueffrage":"Was geschah zwischen dem Moment, in dem er den Kurssturz sah, und dem Verkauf?","rueckmeldung":[{"option":1,"text":"Dass ein Gefühl mitredet, ist nicht das Problem, denn Gefühle liefern Orientierung und Dringlichkeit, und die Angst war hier sogar ein nützlicher Alarm. Verzerrt wird das Urteil erst, wenn das Gefühl die Prüfung der Fakten ersetzt."},{"option":2,"text":"Auf die Art des Gefühls kommt es nicht an: Auch Freude kann das Urteil überstimmen, wenn sie die Prüfung ersetzt. Entscheidend ist, ob das Gefühl allein entscheidet oder ob man es mit Fakten gegenprüft."},{"option":3,"text":"Das Körpersignal zu bemerken war nicht der Fehler, es zeigt, dass etwas Wichtiges passiert ist. Ein Denken ohne solche Signale wäre nicht besser, sondern orientierungslos. Problematisch ist nur, es ungeprüft in eine Handlung umzusetzen."}],"familie":"innehalten-bei-druck","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","seite":"4–5 (Manuskriptzählung)","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Peters, E. (2011): Affect and Emotion. In: Fischhoff, Brewer & Downs (Hg.): Communicating Risks and Benefits: An Evidence-Based User's Guide. FDA","oeffentlich":false}],"thema":"Geld und Zahlen"},{"id":"qx-h-024","clusterId":"H","werkstueckRef":"H.1.4","stufe":4,"question":"Eine Wissenschaftsjournalistin schreibt: „Der Neurologe Antonio Damasio hat bewiesen, dass Körpersignale unsere Entscheidungen lenken. Der Beweis ist ein Kartenspiel-Experiment.“ Welche Rückfrage prüft diese Behauptung am besten?","options":["Wie viele Personen haben teilgenommen, und wie bekannt ist der Forscher, der das Experiment durchgeführt hat?","Lässt sich das Ergebnis auch ohne Körpersignale erklären, etwa weil die Teilnehmer die Strategie bewusst kannten?","Wurden die Teilnehmer vorab ausreichend über Ziel und Ablauf informiert, bevor das Experiment begann?","Gibt es neben dem Kartenspiel weitere Patientenfälle, die mit der Hypothese vereinbar sind und sie stützen?"],"correctIndex":1,"explanation":"Wer „bewiesen“ sagt, muss ausschließen, dass es eine einfachere Erklärung für dasselbe Ergebnis gibt. Genau das ist hier fraglich: Maia und McClelland (2004) fanden, dass Teilnehmer dieses Kartenspiels die günstige Strategie bewusst kennen, und zwar zuverlässiger, als sie danach handeln. Dann lässt sich das Verhalten möglicherweise auch ohne unbewusste Körpersignale erklären. Dunn u. a. (2006) kommen zu dem Schluss, dass die Einwände die Hypothese nicht widerlegen; sie sei eine elegante Theorie, die zusätzliche empirische Stützung braucht. „Bewiesen“ ist also zu stark. Gesichert ist nur: Die Hypothese ist einflussreich, aber umstritten, und bislang weder bewiesen noch widerlegt. Die anderen Rückfragen sind nicht sinnlos, klären aber nicht, ob die Deutung des Ergebnisses trägt: Stichprobengröße und Bekanntheit des Forschers sagen nichts darüber, ob es eine sparsamere Erklärung gibt. Die Aufklärung der Teilnehmer betrifft nicht die Frage, ob die Deutung des Ergebnisses trägt. Und weitere passende Einzelfälle bestätigen eine Deutung noch nicht, solange eine Alternativerklärung offen bleibt.","coreRule":"⚡ Bevor du „bewiesen“ akzeptierst, frage: Gibt es eine einfachere Erklärung für dasselbe Ergebnis?","beleg":"Werkstück H.1.4 (Kernidee; Kontext & Tiefe); Fn. gl-h-somatisch (Damasio 1994, Kap. 8–9; Dunn/Dalgleish/Lawrence 2006, S. 239–271; Maia/McClelland 2004, PNAS 101(45), S. 16075–16080, hier S. 16075)","status":"entwurf","scenario":"Die Hypothese besagt, dass Körpersignale („somatische Marker“) Entscheidungen lenken, noch bevor wir die Regeln bewusst durchschauen. Als zentraler Beleg gilt ein Kartenspiel-Experiment, in dem gesunde Testpersonen und Patienten mit Schäden im Stirnhirn aus vier Kartenstapeln mit unterschiedlichem Gewinn- und Verlustrisiko ziehen.","kurz":"Wer „bewiesen“ sagt, muss eine einfachere Erklärung ausschließen. Hier ist sie offen: Die Teilnehmer kannten die günstige Strategie womöglich bewusst. Dann ließe sich ihr Verhalten auch ohne Körpersignale erklären, und „bewiesen“ ist zu stark.","prueffrage":"Was genau taten die Testpersonen im Kartenspiel, und was davon wurde tatsächlich gemessen?","rueckmeldung":[{"option":0,"text":"Die Teilnehmerzahl ist durchaus eine sinnvolle Rückfrage, denn kleine Gruppen tragen weniger. Die Bekanntheit des Forschers sagt aber nichts über die Deutung. Beides klärt nicht, ob es eine sparsamere Erklärung für dasselbe Ergebnis gibt."},{"option":2,"text":"Die Aufklärung der Teilnehmer ist eine Frage der Versuchsdurchführung, und die kann ihre Berechtigung haben. Für den Beweisanspruch ist sie aber nicht entscheidend, denn sie betrifft nicht, ob die Deutung des Ergebnisses trägt."},{"option":3,"text":"Weitere Fälle könnten die Hypothese durchaus zusätzlich stützen, und das wird auch gefordert. Passende Einzelfälle bestätigen eine Deutung aber noch nicht, solange eine Alternativerklärung für dasselbe Ergebnis offen bleibt."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Maia, T. V. & McClelland, J. L. (2004): A reexamination of the evidence for the somatic marker hypothesis. PNAS 101(45), 16075–16080 (PMC-Fassung)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC528759/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dunn, Dalgleish & Lawrence (2006): The somatic marker hypothesis: A critical evaluation (Autorenmanuskript, MRC CBU)","oeffentlich":true,"url":"https://www.mrc-cbu.cam.ac.uk/personal/tim.dalgleish/dunnsmhreview.pdf","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-h-025","clusterId":"H","werkstueckRef":"H.1.5","stufe":1,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Beide überziehen: Dass Gewohnheiten die Konzentration prägen, ist plausibel, wie stark sich das im Gehirn zeigt, aber offen. Training kann helfen, am ehesten an der gefragten Tätigkeit.","Die Schwester hat recht: Das erwachsene Gehirn ist im Kern festgelegt, deshalb kann sich seine Konzentrationsfähigkeit nicht mehr nennenswert verändern, auch nicht durch Üben.","Der Bruder hat recht: Das Gehirn ist in jedem Alter beliebig formbar, deshalb stellt bloßes Üben die alte Konzentration sicher und vollständig wieder her.","Beide liegen falsch: Konzentrationsfähigkeit ist ausschließlich angeboren, deshalb hängt sie weder von früheren Gewohnheiten noch von Übung ab, auch nicht in Teilen."],"correctIndex":0,"explanation":"Die Schwester nimmt an, das erwachsene Gehirn sei starr. Das ist überholt: Auch das erwachsene Gehirn verändert sich durch Erfahrung, wie stark und wie dauerhaft, ist allerdings umstritten; ihr „da lässt sich nichts mehr machen“ ist daher zu sicher. Der Bruder liegt in der Richtung näher an der Sache, denn Konzentration lässt sich üben, am ehesten an genau der Tätigkeit, für die man sie braucht; dass Üben es sicher und vollständig wieder richtet, ist aber ebenso wenig gesichert, und beliebig formbar ist das Gehirn nicht. Dass jahrelange Feed-Gewohnheiten die Konzentration geschwächt haben, ist plausibel, ob und wie stark sich das im Gehirn selbst zeigt, ist offen. Auch „ausschließlich angeboren“ stimmt nicht: Unterschiede in der Aufmerksamkeitssteuerung sind zum Teil erblich, trotzdem lässt sie sich üben.","coreRule":"⚡ Das Gehirn formt sich nach dem, was du wiederholst, ohne Rücksicht auf den Nutzen. Wie stark und wie dauerhaft, bleibt eine offene Frage.","quote":"","quoteLabel":"","beleg":"Werkstück H.1.5 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Jemand verbringt seit Jahren fast jede freie Minute mit kurzen Videos und Nachrichten-Feeds. Heute fällt es ihm schwer, länger als ein paar Minuten bei einem anspruchsvollen Text zu bleiben. Seine Schwester sagt: „Ich bin mir sicher, dass sich sein Gehirn dadurch dauerhaft verschlechtert hat, da lässt sich nichts mehr machen.“ Er antwortet: „Das glaube ich nicht. Ich muss nur wieder üben, dann wird es besser.“","kurz":"Beide überziehen: Dass jahrelange Gewohnheiten die Konzentration geprägt haben, ist plausibel, wie stark und dauerhaft, ist offen. Üben kann helfen, am ehesten an der Tätigkeit selbst; „da lässt sich nichts mehr machen“ ist ebenso zu sicher wie die Erwartung, Üben richte alles.","prueffrage":"Was lässt sich in seinem Alltag tatsächlich beobachten, wenn er statt Feeds regelmäßig längere Texte liest?","rueckmeldung":[{"option":1,"text":"Dass jahrelange Gewohnheiten Spuren hinterlassen, ist einleuchtend. Starr ist das erwachsene Gehirn aber nicht, es verändert sich durch Erfahrung; wie stark und dauerhaft, ist umstritten. „Da lässt sich nichts mehr machen“ ist zu sicher."},{"option":2,"text":"Konzentration lässt sich üben, so weit liegt er richtig. Beliebig formbar ist das Gehirn aber nicht, und ob die alte Ausdauer durch Üben ganz zurückkommt, ist offen. „Sicher und vollständig“ verspricht mehr, als sich belegen lässt."},{"option":3,"text":"Ein Teil der Unterschiede in der Aufmerksamkeitssteuerung ist tatsächlich erblich. „Ausschließlich angeboren“ geht aber zu weit: Aufmerksamkeit lässt sich üben, und dass Gewohnheiten sie schwächen können, ist plausibel."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Malik, Stemplewski & Maciaszek (2022): The Effect of Juggling as Dual-Task Activity on Human Neuroplasticity: A Systematic Review. Int. J. Environ. Res. Public Health 19(12), 7102","oeffentlich":true,"doi":"10.3390/ijerph19127102","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fan, Wu, Fossella & Posner (2001): Assessing the heritability of attentional networks. BMC Neuroscience 2, 14","oeffentlich":true,"doi":"10.1186/1471-2202-2-14"},{"typ":"literatur","kurz":"Thomas, C. & Baker, C. I. (2013): Teaching an adult brain new tricks: a critical review of evidence for training-dependent structural plasticity in humans. NeuroImage 73, 225–236","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-h-026","clusterId":"H","werkstueckRef":"H.1.5","stufe":2,"question":"Welcher Plan ist am ehesten geeignet, Konzentration wieder aufzubauen, und warum?","scenario":"Du merkst, dass du kaum noch ein langes Buch am Stück lesen kannst und bei jeder Mikropause zum Smartphone greifst. Du willst deine Konzentration gezielt trainieren und überlegst, wie du vorgehst.","options":["Jeden Tag 15 bis 30 Minuten ununterbrochen eine einzige anspruchsvolle Aufgabe bearbeiten, ohne Smartphone in Sichtweite, und das konsequent wiederholen.","Einmal pro Woche einen ganzen Tag komplett offline gehen und im Alltag weiter wie bisher zwischen den Aufgaben hin und her springen.","Jeden Tag bewusst noch schneller zwischen mehreren Aufgaben wechseln, bis das Gehirn gelernt hat, alles gleichzeitig im Blick zu behalten.","Die Konzentrationsfähigkeit als feste Begabung hinnehmen und alle Aufgaben in Fünf-Minuten-Häppchen zerlegen, damit nichts anstrengend wird."],"correctIndex":0,"explanation":"Geübt wird, was man tatsächlich tut: Wer Konzentration will, muss genau diese Tätigkeit regelmäßig und in kleinen, machbaren Dosen üben. Sinnvoll sind dafür tägliche, ununterbrochene Übungsphasen von 15 bis 30 Minuten. Ein Offline-Tag pro Woche übt Konzentration an den übrigen Tagen nicht, dort bleibt alles beim Alten. Am Anfang wird das Gehirn rebellieren und nach Ablenkung verlangen, mit konsequenter Wiederholung wird der Weg der Konzentration aber wieder frei. Schnelles Wechseln übt das Wechseln, nicht das Dranbleiben. Wer Konzentration als feste Gabe hinnimmt und Aufgaben immer nur häppchenweise bearbeitet, übt sie nie. Unterschiede in der Aufmerksamkeitssteuerung sind zwar zum Teil erblich, aber auch geübt werden kann sie; besser wird man dabei vor allem in dem, was man übt, ohne sicheren Übertrag auf ungeübte Aufgaben (Owen u. a. 2010). Für die Übung der Konzentration spricht also einiges; ob ständige Ablenkung das Gehirn messbar umgebaut hat, ist dagegen noch offen.","coreRule":"⚡ Wer eine Fähigkeit stärken will, übt sie regelmäßig und gezielt an genau der Tätigkeit, für die er sie braucht.","beleg":"Werkstück H.1.5 (Die Schmiede-Übung; Anwendung & Relevanz); Fn. gl-h-aufmerksamkeit (Fan u. a. 2001; Rueda u. a. 2005)","status":"entwurf","kurz":"Konzentration lässt sich am ehesten aufbauen, indem man sie regelmäßig in machbaren Einheiten tatsächlich übt, etwa täglich 15 bis 30 Minuten ungestört. Der naheliegende Fehler ist, Entlastung oder Abwechslung mit Training zu verwechseln.","prueffrage":"Was genau tust du während der Zeit, die du als Training einplanst, und wie oft kommt das vor?","rueckmeldung":[{"option":1,"text":"Ein Tag ohne Smartphone entlastet und kann guttun. Konzentration übt er aber nicht, denn an den übrigen Tagen läuft alles wie bisher, und genau dort fehlt das regelmäßige Dranbleiben."},{"option":2,"text":"Mehrere Dinge im Blick zu behalten klingt nach Training für den Kopf. Wer schneller wechselt, übt jedoch das Wechseln, nicht das Dranbleiben, und gerade das fehlt dir ja."},{"option":3,"text":"Kleine, machbare Einheiten sind sinnvoll, und Unterschiede in der Aufmerksamkeit sind zum Teil erblich. Wer sie aber als feste Gabe hinnimmt und nie länger dranbleibt, übt sie nicht, obwohl sie sich durchaus üben lässt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Owen, Hampshire, Grahn u. a. (2010): Putting brain training to the test. Nature 465(7299), 775–778 (frei als PMC2884087)","oeffentlich":true,"doi":"10.1038/nature09042","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rueda, Rothbart, McCandliss, Saccomanno & Posner (2005): Training, maturation, and genetic influences on the development of executive attention. PNAS 102(41), 14931–14936 (frei als PMC1253585)","oeffentlich":true,"doi":"10.1073/pnas.0506897102","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-h-027","clusterId":"H","werkstueckRef":"H.1.5","stufe":3,"question":"Welche Schlussfolgerung stützt eine große Online-Studie mit über 11.000 Teilnehmern, in der sechs Wochen lang Denkspiele geübt wurden, am besten?","scenario":"Ein Werbetext verspricht: „Zehn Minuten Gehirntraining täglich verbessern Ihre Konzentration im ganzen Alltag.“ Zur Prüfung des Versprechens liegt eine große Online-Studie vor: Über 11.000 Menschen übten sechs Wochen lang Denkspiele. Alle geübten Aufgaben wurden deutlich besser. Bei ungeübten Aufgaben, auch bei eng verwandten, zeigte sich keine Verbesserung.","options":["Wer eine Aufgabe übt, wird vor allem in dieser Aufgabe besser; ein Gewinn für ungeübte Aufgaben ist nicht belegt.","Wer eine Aufgabe übt, wird auch in ungeübten Aufgaben besser; der Transfer ist der eigentliche Nutzen des Trainings.","Wer als Erwachsener übt, verbessert sich nicht; nur Kinder profitieren überhaupt von einem Training.","Wer eine Aufgabe übt, wird darin nicht besser; das Gehirn bleibt durch Training völlig unverändert."],"correctIndex":0,"explanation":"Die Teilnehmer wurden in den geübten Aufgaben deutlich besser, in ungeübten Aufgaben aber nicht, selbst wenn diese den geübten kognitiv nahestanden. Das stützt: Übung wirkt vor allem dort, wo geübt wurde. Der Werbeslogan behauptet aber genau den Sprung vom Spiel auf den „ganzen Alltag“. Dafür fehlt hier der Beleg. Wer Konzentration für eine bestimmte Tätigkeit braucht, übt sie deshalb am besten an dieser Tätigkeit selbst. Dass Aufmerksamkeit trainierbar ist, bleibt davon unberührt: Die geübten Aufgaben wurden ja besser.","coreRule":"⚡ Übung wirkt vor allem im Geübten: Trainiere Konzentration an der Tätigkeit, die du brauchst, nicht an Ersatzspielen.","beleg":"Werkstück H.1.5 (Kontext & Tiefe: Konzentration als Fähigkeit); Fn. gl-h-aufmerksamkeit (Owen u. a. 2010, Nature 465(7299), S. 775–778)","status":"entwurf","kurz":"Verbessert haben sich die Teilnehmer nur in den geübten Aufgaben, nicht in ungeübten, auch nicht in eng verwandten. Der Fehler liegt darin, vom besseren Spielergebnis auf besseren „Alltag“ zu schließen: Dieser Sprung ist hier nicht belegt.","prueffrage":"In welchen Aufgaben genau zeigte sich eine Verbesserung, und wie weit liegen diese vom beworbenen „ganzen Alltag“ entfernt?","rueckmeldung":[{"option":1,"text":"Dass geübte Aufgaben besser werden, stimmt, und genau daraus wird gern mehr gemacht. Bei den ungeübten Aufgaben, selbst den eng verwandten, zeigte sich aber keine Verbesserung. Der Transfer ist hier gerade nicht belegt."},{"option":2,"text":"Eine Altersaussage klingt plausibel, weil Lernen oft mit Jugend verbunden wird. Über das Alter der Teilnehmer ist aber nichts gesagt, und die geübten Aufgaben wurden deutlich besser. Eine Grenze zwischen Kindern und Erwachsenen folgt daraus nicht."},{"option":3,"text":"Die Skepsis gegenüber dem Werbeversprechen ist berechtigt, schießt hier aber über das Ziel hinaus. Die geübten Aufgaben wurden ja deutlich besser. Es fehlt nur der Beleg für den Übertrag auf anderes, nicht die Wirkung des Übens selbst."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Owen, Hampshire, Grahn u. a. (2010): Putting brain training to the test. Nature 465(7299), 775–778 (frei als PMC2884087)","oeffentlich":true,"doi":"10.1038/nature09042","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-h-028","clusterId":"H","werkstueckRef":"H.1.5","stufe":4,"question":"In einem Vortrag zitiert jemand den Satz „Neurons that fire together, wire together“ und fügt hinzu: „Das hat Donald Hebb 1949 wörtlich so geschrieben.“ Du willst die Aussage prüfen. Welche Überlegung bringt dich am weitesten?","options":["Der Satz ist inhaltlich richtig und wird Hebb zugeschrieben, also muss er auch wörtlich von ihm stammen.","Eine so eingängige Formel stammt eher aus einer späteren Zusammenfassung, das lässt sich an der Originalquelle prüfen.","Der Satz ist so weit verbreitet, dass er aus der Originalquelle stammen muss, sonst würde ihn niemand so oft zitieren.","Ob ein Zitat wörtlich stimmt, ist unwichtig, solange der Inhalt der Theorie in der Wiedergabe korrekt bleibt."],"correctIndex":1,"explanation":"Eine Zuschreibung ist erst belegt, wenn man die Originalquelle kennt. Hier ist das besonders wichtig: Die Formel ist so griffig, dass sie eher wie eine spätere Verdichtung klingt als wie ein Satz aus einer Fachpublikation. Tatsächlich ist die Kurzformel keine Originalformulierung Hebbs („The Organization of Behavior“, 1949), sondern eine spätere, griffigere Zusammenfassung seines Postulats. Sie wird meist Carla Shatz zugeschrieben („cells that fire together wire together“, Scientific American, 1992); populär wurde sie erst rund vier Jahrzehnte nach Hebb. Hebbs eigener Wortlaut ist deutlich sperriger: Wenn das Axon einer Zelle A nah genug ist, um eine Zelle B zu erregen, und wiederholt an deren Aktivierung beteiligt ist, tritt in einer oder beiden Zellen ein Wachstums- oder Stoffwechselprozess ein, der die Effizienz von A bei der Erregung von B erhöht. Selbst inhaltlich trifft die Kurzformel Hebb nur ungefähr: Bei ihm ist A an der Erregung von B ursächlich beteiligt, die Formel spricht nur von gleichzeitigem Feuern. Die Behauptung „wörtlich so geschrieben“ stimmt jedenfalls nicht, und weder Verbreitung noch Plausibilität ersetzen den Blick in die Quelle.","coreRule":"⚡ Griffige Zitate prüfen: Je eingängiger die Formel, desto eher lohnt der Blick in die Originalquelle, bevor man sie einer Person zuschreibt.","beleg":"Werkstück H.1.5 (Kontext & Tiefe); Fn. gl-h-3 (Hebb, The Organization of Behavior, 1949; Shatz, Scientific American, September 1992)","status":"entwurf","scenario":"","kurz":"Eine Zuschreibung ist erst belegt, wenn man die Originalquelle kennt. Eine so griffige Formel klingt eher nach späterer Verdichtung als nach Fachpublikation, und „wörtlich“ lässt sich nur am Originaltext prüfen. Den Inhalt sinngemäß zu treffen, genügt dafür nicht.","prueffrage":"Behauptet der Vortragende nur, dass der Gedanke von Hebb stammt, oder auch, dass Hebb genau diese Worte benutzt hat?","rueckmeldung":[{"option":0,"text":"Inhaltlich trifft der Satz Hebbs Gedanken ungefähr, und die Zuschreibung ist verbreitet. Daraus folgt aber nicht, dass Hebb genau diese Worte schrieb: Die Formel ist eine spätere Verdichtung, sein eigener Wortlaut ist deutlich sperriger."},{"option":2,"text":"Weite Verbreitung zeigt, dass die Formel bekannt und eingängig ist, nicht, woher sie stammt. Ein Satz kann tausendfach zitiert werden und trotzdem aus einer späteren Zusammenfassung kommen; hier wurde er erst Jahrzehnte nach Hebb populär."},{"option":3,"text":"Sinngemäß trifft die Formel Hebbs Gedanken ungefähr. Der Vortragende behauptet aber ausdrücklich „wörtlich“, und diese Behauptung lässt sich an der Quelle als falsch erweisen. Wer so genau auftritt, muss auch so genau sein."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Liberman, M. (21.04.2016): Language Log, Beitrag zu „fire together, wire together“","oeffentlich":true,"url":"https://languagelog.ldc.upenn.edu/nll/?p=25194","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hebb, D. O. (1949): The Organization of Behavior. New York: Wiley","oeffentlich":false},{"typ":"literatur","kurz":"Shatz, C. J. (1992): The developing brain. Scientific American 267(3)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-h-029","clusterId":"H","werkstueckRef":"H.1.6","stufe":1,"question":"Was erklärt am besten, warum du ihr nicht helfen konntest und selbst erschöpft bist?","scenario":"Tante Gerda ruft panisch an: „Die da oben vergiften das Trinkwasser!“ Du hörst zu und schwingst ganz mit ihr mit: Ihre Angst wird zu deiner Angst, ihre Wut zu deiner Wut. Nach dem Anruf zitterst du, fühlst dich hoffnungslos und erschöpft. Gerda hat sich nicht beruhigt, und dir graut vor dem nächsten Anruf.","options":["Du hast ihre Gedanken kühl zerlegt und ihre Gefühle ausgeblendet, daher spürte sie keine Zuwendung und du bliebst innerlich leer.","Du hast dich zu intensiv um ihr Wohlergehen gekümmert und dabei deine eigenen Kräfte aufgebraucht, daher blieb nichts für das Gespräch übrig.","Du hast ihre Panik übernommen statt dich davon zu lösen, daher warst du selbst überwältigt und konntest ihr keinen ruhigen Halt bieten.","Du hast ihre Beweggründe nicht nachvollziehen können und dich deshalb innerlich zurückgezogen, daher ging das Gespräch ins Leere."],"correctIndex":2,"explanation":"Wer die Gefühle des anderen ungefiltert übernimmt, schwingt voll mit ihm mit. Bei Panik heißt das: Zwei Menschen sind gleichzeitig aufgewühlt, und keiner ist übrig, der Halt geben könnte. Dieses Mitschwingen kann zu „Empathic Distress“ führen, einer emotionalen Überwältigung, die bis zu Lähmung, Rückzug oder Burnout reichen kann. Wer dagegen die Angst versteht, ohne sie zu übernehmen, und ruhig, aber warm bleibt, kann tatsächlich helfen; die Erschöpfung kommt hier nicht vom Sorgen an sich, sondern vom Übernehmen fremder Panik. Kühles Zerlegen ihrer Gedanken würde ein anderes Problem erzeugen: Gerda fühlte sich wie unter dem Mikroskop und bliebe unverstanden.","coreRule":"⚡ Wer die Panik des anderen spiegelt, kann ihm nicht helfen: Verstehen und Fürsorge brauchen Abstand zum fremden Gefühl.","beleg":"Werkstück H.1.6 (Der Anruf bei Tante Gerda, Szenario 1; Kontext & Tiefe)","status":"entwurf","kurz":"Wer fremde Panik ungefiltert mitfühlt, wird selbst aufgewühlt, und dann ist niemand mehr da, der Halt gibt. Der Fehler liegt darin, Gerdas Angst zu übernehmen, statt sie zu verstehen und dabei ruhig, aber warm zu bleiben.","prueffrage":"Was hast du während des Anrufs gesagt oder getan, das Gerda hätte beruhigen können?","rueckmeldung":[{"option":0,"text":"Kühles Zerlegen hätte Gerda tatsächlich nicht erreicht. Nur lief es anders: Du hast ihre Gefühle nicht ausgeblendet, sondern so stark mitempfunden, dass sie zu deinen eigenen wurden."},{"option":1,"text":"Dass du erschöpft bist, stimmt. Die Ursache ist aber nicht zu viel Sorge an sich, sondern dass du Gerdas Panik übernommen hast, statt dich davon zu lösen."},{"option":3,"text":"Zurückgezogen hast du dich im Gespräch nicht, im Gegenteil: Du hast ihre Angst und Wut vollständig mitempfunden. Gefehlt hat der Abstand dazu, also ihre Angst zu verstehen, ohne sie zu übernehmen."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben"},{"id":"qx-h-030","clusterId":"H","werkstueckRef":"H.1.6","stufe":2,"question":"Wie reagierst du in diesem Gespräch am besten?","options":["Du überlegst, warum sie das glaubt, sagst dann kurz, dass du ihre Angst wahrnimmst, und bleibst danach ruhig und zugewandt, um ihr beim Einordnen zu helfen.","Du übernimmst ihre Aufregung ganz, redest genauso besorgt und fühlst ihre Angst mit, damit sie sich vollkommen verstanden fühlt.","Du analysierst nüchtern ihre Denkfehler, widerlegst sie Punkt für Punkt und zeigst am Ende noch ein wenig Mitgefühl.","Du hältst dich emotional komplett heraus und gehst sachlich ihre Argumente durch, ohne ihre Angst irgendwie zu erwähnen."],"correctIndex":0,"explanation":"Hilfreich ist eine Abfolge: erst verstehen, warum die Person so denkt, dann ihr Gefühl kurz spiegeln („Ich höre, dass dir das Angst macht“) und schließlich ruhig und warm Halt geben. Wer ihre Panik voll übernimmt, wird selbst überwältigt und kann nicht mehr helfen: Man ertrinkt mit dem Ertrinkenden, statt ihm den Rettungsring zuzuwerfen. Wer nur kühl analysiert, wirkt auf sie wie ein Insekt unter dem Mikroskop, und ein Gespräch, in dem das Gefühl gar nicht vorkommt, erreicht sie nicht. Das kurze Spiegeln signalisiert, dass du ihre Angst ernst nimmst, ohne dass sie auf dich übergeht.","coreRule":"⚡ Verstehen, kurz spiegeln, dann ruhig und warm Halt geben.","quote":"Du fühlst nicht mit ihr, du fühlst für sie.","quoteLabel":"Merksatz:","beleg":"Werkstück H.1.6 (Szenario 3: Die Warme Brücke; Kontext & Tiefe: strategische Abfolge)","status":"entwurf","scenario":"Deine Tante ruft dich panisch an: Sie ist überzeugt, dass „die da oben“ das Trinkwasser vergiften. Sie redet schnell, ihre Stimme zittert. Du willst ihr helfen, ohne selbst in ihre Panik hineingezogen zu werden und ohne sie wie einen Fall zu behandeln.","kurz":"Erst zu verstehen, warum sie so denkt, und ihre Angst kurz auszusprechen, gibt ihr das Gefühl, ernst genommen zu werden, ohne dass die Panik auf dich übergeht. Aus dieser Ruhe heraus kannst du ihr beim Einordnen helfen.","prueffrage":"Was hättest du an ihrer Stelle in diesem Moment von der Person am anderen Ende der Leitung gebraucht?","rueckmeldung":[{"option":1,"text":"Verständnis zu zeigen ist wichtig, ihre Aufregung zu übernehmen hilft ihr aber nicht: Wer selbst überwältigt ist, hilft nicht mehr beim Einordnen und bestätigt ihre Angst eher. Kurzes Spiegeln zeigt Verständnis, ohne dass das Gefühl überspringt."},{"option":2,"text":"Gründliches Prüfen der Argumente hat durchaus seinen Platz. Kommt das Gefühl aber erst am Schluss, fühlt sie sich wie ein Fall behandelt und hört kaum noch zu. Das Verstehen und das kurze Spiegeln gehören an den Anfang."},{"option":3,"text":"Ruhig und sachlich zu bleiben schützt dich davor, in die Panik zu geraten. Spricht aber niemand ihre Angst an, fühlt sie sich nicht ernst genommen, und die Argumente kommen bei ihr kaum an. Ein kurzer Satz dazu reicht schon."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben"},{"id":"qx-h-031","clusterId":"H","werkstueckRef":"H.1.6","stufe":3,"question":"Wo liegt das Risiko in dieser Haltung des Kollegen?","scenario":"Ein Kollege sagt über seinen Onkel, der an eine Verschwörungserzählung glaubt: „Ich durchschaue seine Logik perfekt und kann jeden Schritt nachvollziehen. Aber er wirft mir vor, kalt zu sein, und fühlt sich wie unter dem Mikroskop.“","options":["Er fühlt zu stark mit dem Onkel mit, deshalb droht ihm Überforderung und am Ende der Rückzug aus dem Gespräch und aus der Beziehung zu ihm.","Er versteht die Logik des Onkels noch nicht genau genug; mit mehr Wissen über dessen Quellen und Argumente würde die Kälte von allein verschwinden.","Er nutzt das Verstehen nur zum Analysieren, ohne Fürsorge für den Onkel; so wirkt es wie Sezieren und dient nicht mehr dem Helfen.","Er sorgt sich zu sehr um das Wohlergehen des Onkels und verliert dadurch die nötige sachliche Distanz zum Thema."],"correctIndex":2,"explanation":"Der Kollege versteht den Onkel gedanklich sehr gut, aber dieses Verstehen bleibt ohne Wärme und ohne den Wunsch zu helfen. Der Onkel spürt das: Er fühlt sich analysiert statt ernst genommen. Das Problem ist also nicht zu wenig Verständnis, sondern zu wenig Fürsorge. Wer nur versteht, kann sein Gegenüber im schlimmsten Fall zum Untersuchungsobjekt machen oder sich überlegen fühlen. Wer dagegen zu stark mitleidet, wird von den fremden Gefühlen überschwemmt und zieht sich irgendwann erschöpft zurück; dafür gibt es hier aber keinen Hinweis, denn der Kollege fühlt ja gerade wenig. Ein Gespräch kommt in Gang, wenn zum Verstehen die Sorge um den anderen dazukommt, ohne dessen Panik zu übernehmen.","coreRule":"⚡ Verstehen ohne Fürsorge wird kalt, Fürsorge ohne Abstand wird Panik.","quote":"","quoteLabel":"","beleg":"Werkstück H.1.6 (Der Kipppunkt; Red Flags: Anzeichen für ein Ungleichgewicht; Szenario 2: Die Kalte Analyse)","status":"entwurf","kurz":"Der Kollege versteht den Onkel gedanklich sehr gut, doch ohne Sorge um ihn wirkt das Verstehen wie Sezieren. Wer meint, mehr Analyse löse das Problem, übersieht, dass dem Onkel Zuwendung fehlt, nicht Erklärung.","prueffrage":"Was sagt der Kollege über sein eigenes Verständnis, und was sagt der Onkel über das Gespräch?","rueckmeldung":[{"option":0,"text":"Zu starkes Mitleiden kann tatsächlich erschöpfen und zum Rückzug führen. Hier gibt es dafür aber keinen Hinweis: Der Onkel erlebt den Kollegen als kalt, und genau das spricht gegen übermäßiges Mitfühlen."},{"option":1,"text":"Mehr Wissen über Quellen und Argumente würde das Verstehen vertiefen, das hier aber schon sehr gründlich ist: Der Kollege kann jeden Schritt nachvollziehen. Die Kälte kommt daher nicht von einer Lücke im Verständnis, sondern von fehlender Zuwendung."},{"option":3,"text":"Zu viel Sorge kann die Distanz zur Sache tatsächlich aufweichen. Auf diesen Kollegen passt das aber nicht: Er fühlt wenig, und der Onkel erlebt ihn als kalt. Das Problem ist nicht zu viel, sondern zu wenig Fürsorge."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Zusammenleben"},{"id":"qx-h-032","clusterId":"H","werkstueckRef":"H.1.6","stufe":4,"question":"Eine Kollegin sagt: „Mitleiden und Mitgefühl sind im Gehirn im Grunde dasselbe.“ Welche Beobachtung widerspricht dieser Behauptung am stärksten?","options":["Nach dem Mitempfinden-Training ist vor allem das Schmerz- und Negativsystem aktiver, nach dem Fürsorge-Training vor allem das Belohnungs- und Zugehörigkeitssystem.","Nach beiden Trainings ist vor allem das Belohnungs- und Zugehörigkeitssystem aktiver, das Schmerz- und Negativsystem bleibt jeweils unverändert.","Nach beiden Trainings ist dasselbe Muster aus Schmerz- und Belohnungsaktivität zu sehen, nur unterschiedlich stark.","Nach dem Mitempfinden-Training ist das Schmerzsystem aktiver, nach dem Fürsorge-Training sind insgesamt alle gemessenen Areale ruhiger."],"correctIndex":0,"explanation":"Die Behauptung setzt Mitleiden und Mitgefühl gleich. Am stärksten widerspricht ihr ein Befund, in dem beide Trainings jeweils ein anderes Hirnsystem ansprechen. Genau das zeigten Trainingsstudien von Klimecki und Kollegen (2014): Nach dem Empathie-Training waren Insula und anteriorer cingulärer Cortex aktiver (Schmerz, negativer Affekt), nach dem Mitgefühls-Training ventrales Striatum und medialer orbitofrontaler Cortex (Belohnung, Zugehörigkeit). Sprechen beide Trainings dasselbe System an, ob allein oder als gleiches Muster in unterschiedlicher Stärke, ist kein eigener Weg erkennbar, und die Behauptung bliebe stehen; ein bloßes Ruhigerwerden aller Areale nach der Fürsorge zeigt ebenfalls kein eigenes System. Die Begriffe folgen der Arbeitsgruppe um Singer und Klimecki; andere Autoren teilen anders ein.","coreRule":"⚡ Wenn zwei Dinge angeblich dasselbe sind, prüfe, ob sie sich unter Test unterschiedlich verhalten: Mitleiden und Mitgefühl lassen sich im Gehirn unterscheiden.","beleg":"Werkstück H.1.6 (Kontext & Tiefe); Fn. gl-h-empathie (Singer/Klimecki 2014, Current Biology 24(18), S. R875–R878; Klimecki u. a. 2014, SCAN 9(6), S. 873–879)","status":"entwurf","scenario":"In einer Trainingsstudie übt eine Gruppe zunächst, die Gefühle anderer mitzuempfinden, und anschließend, sich fürsorglich um andere zu sorgen. Dabei wird die Hirnaktivität gemessen.","kurz":"Die Gleichsetzung fällt erst, wenn die Trainings verschiedene Systeme ansprechen: Mitempfinden eher solche für Schmerz und negativen Affekt, Fürsorge eher solche für Belohnung und Zugehörigkeit. Bloße Unterschiede in der Stärke ließen die Behauptung bestehen.","prueffrage":"Was genau behauptet die Kollegin über das Gehirn, und welches Messergebnis wäre mit ihrer Behauptung noch vereinbar?","rueckmeldung":[{"option":1,"text":"Dass beide Trainings vor allem das Belohnungssystem aktivieren, wäre ein klarer Befund. Er zeigt aber für beide dasselbe System und stützt die Gleichsetzung eher; widersprechen würde ihr erst ein anderes System je Training."},{"option":2,"text":"Ein Unterschied in der Stärke wirkt wie Verschiedenheit. Ist das Muster aber dasselbe, sprechen beide Trainings dieselben Systeme an, und die Gleichsetzung von Mitleiden und Mitgefühl bliebe bestehen."},{"option":3,"text":"Dass das Schmerzsystem nach dem Mitempfinden aktiver ist, passt zum Befund. Dass nach der Fürsorge bloß alle Areale ruhiger sind, zeigt aber kein eigenes System; am stärksten widerspricht erst ein anderes, aktiveres System je Training."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klimecki, Leiberg, Ricard & Singer (2014): Differential Pattern of Functional Brain Plasticity After Compassion and Empathy Training. Social Cognitive and Affective Neuroscience 9(6)","oeffentlich":true,"doi":"10.1093/scan/nst060","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4040103/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Singer & Klimecki (2014): Empathy and Compassion. Current Biology 24(18), R875–R878 (Verlagsseite hier nicht geöffnet; Register b2a0fd0f299 am Volltext bestätigt)","oeffentlich":false,"doi":"10.1016/j.cub.2014.06.054"}],"thema":"Psychologie"},{"id":"qx-h-033","clusterId":"H","werkstueckRef":"H.2.1","stufe":1,"question":"Welche Reaktion ist in diesem Moment am sinnvollsten und warum?","options":["„Das klingt, als würdest du dich von Leuten wie mir nicht ernst genommen fühlen. Habe ich das richtig verstanden?“","„Das stimmt einfach nicht. Ich zeige dir gleich die Zahlen, die belegen, dass du falsch liegst.“","„Du bist gerade völlig unsachlich. Komm wieder, wenn du dich beruhigt hast und vernünftig argumentieren kannst.“","„Okay, da hast du vielleicht recht. Lass uns einfach das Thema wechseln, damit der Abend ruhig bleibt.“"],"correctIndex":0,"explanation":"In einem eskalierten Gespräch hat das emotionale System 1 die Kontrolle, und System 2 arbeitet nur noch als dessen Anwalt. Ein Fakten-Argument kommt in diesem Zustand kaum an und nährt eher den Streit. Wer stattdessen das Gefühl aufgreift, ohne der Behauptung zuzustimmen, nimmt dem Gegenüber das Bedürfnis, lauter zu werden, und öffnet eine Tür für ein echtes Gespräch. Eine Gegenrede mit Zahlen verfehlt dieses Ziel, ein Vorwurf („unsachlich“) ist selbst ein Angriff auf die Person und zwingt das Gegenüber in die Verteidigung. Das bloße Zustimmen zur Behauptung gibt die eigene Position auf, nur um Ruhe zu haben. Ein hitziger Moment verlangt, das Gespräch zu retten, statt Recht zu haben.","coreRule":"⚡ Im Feuer erst das Gefühl aufgreifen, nicht den Inhalt bestätigen und nicht mit Fakten kontern.","quote":"","quoteLabel":"","beleg":"Werkstück H.2.1 (Die Taktische Matrix: vier Kern-Techniken; Kontext & Tiefe)","status":"entwurf","scenario":"Bei einer Familienfeier sagt dein Onkel laut: „Ihr Studierten seid doch alle gleich! Ihr sitzt in eurer arroganten Blase und habt keine Ahnung vom echten Leben!“ Du merkst, wie dein Puls steigt und du am liebsten sofort mit Fakten kontern würdest.","kurz":"Wer das Gefühl hinter der Pauschalaussage aufgreift, ohne ihr zuzustimmen, nimmt dem Onkel den Anlass, lauter zu werden. Gerade jetzt zählt das Gespräch mehr als das Rechthaben, und Zahlen kämen im erhitzten Zustand kaum an.","prueffrage":"Was verrät der Ton deines Onkels über seinen Zustand, und wie viel Offenheit für Zahlen ist da gerade zu erwarten?","rueckmeldung":[{"option":1,"text":"Die Verallgemeinerung ist tatsächlich anfechtbar, und Zahlen können stimmen. Im hitzigen Moment kommen sie aber kaum an und heizen den Streit eher an, weil sich dein Onkel weiter nicht ernst genommen fühlt."},{"option":2,"text":"Dass sein Ton pauschal ist, stimmt. Das Wort „unsachlich“ trifft ihn aber selbst und zwingt ihn in die Verteidigung. Die Aufforderung, wiederzukommen, wenn er ruhig ist, beendet das Gespräch, statt es zu retten."},{"option":3,"text":"Der Wunsch nach einem ruhigen Abend ist verständlich. Wer aber nur zustimmt, um Ruhe zu haben, gibt die eigene Position auf. Es ginge darum, das Gefühl aufzugreifen, ohne der Behauptung recht zu geben."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, Cook, Ecker u. a. (2020): The Debunking Handbook 2020 (doi 10.17910/b7.1182; geöffnet als PDF bei Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"9","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-034","clusterId":"H","werkstueckRef":"H.2.1","stufe":2,"question":"Welche Antwort ist am ehesten geeignet, die Lage zu beruhigen und das Gespräch zu retten, ohne dem Vorwurf zuzustimmen?","scenario":"In einer hitzigen Diskussion ruft dein Gegenüber laut: „Ihr Wissenschaftsgläubigen seid doch alle gleich! Ihr steckt in eurer arroganten Blase und habt keine Ahnung vom echten Leben!“ Du merkst, wie sich dein eigener Puls beschleunigt.","options":["„Du hast völlig recht: Wir Wissenschaftsgläubigen sind arrogant. Lass uns das Thema einfach fallen lassen, bevor es noch unangenehmer wird.“","„Wenn du jetzt pauschal alle über einen Kamm scherst, ist das kein Argument. Ich gehe auf Beleidigungen nicht ein und antworte erst wieder sachlich.“","„Es klingt, als wärst du frustriert und hättest das Gefühl, dass Leute wie ich auf dich herabschauen. Habe ich das richtig verstanden?“","„Ich verstehe deine Wut, aber sie kommt nur daher, dass du die Studienlage nicht kennst. Hier sind die wichtigsten Zahlen dazu.“"],"correctIndex":2,"explanation":"In einem eskalierten Gespräch bestimmen Gefühle und schnelle, intuitive Reaktionen das Geschehen, und Argumente kommen kaum noch an. Wer den Köder ignoriert und stattdessen das dahinterliegende Gefühl benennt, nimmt dem Streit Energie und öffnet eine kleine Tür zum Gespräch. Die richtige Antwort tut genau das und fragt nach, statt zu urteilen. Die Zustimmung zum Vorwurf ist keine Deeskalation, sondern Unterwerfung: Du stimmst einer Aussage zu, die du selbst nicht teilst; ein Gefühl zu validieren ist nicht dasselbe wie den Inhalt zu validieren. Der Hinweis auf „Beleidigungen“ ist ein Gegenvorwurf und verschiebt den Streit auf die Frage, wer sich falsch verhält. Die Antwort mit „Ich verstehe deine Wut, aber …“ behauptet, das Gegenüber kenne die Studienlage nicht, und wirft ein Fakten-Argument ins Feuer, das kaum ankommt und den Streit eher nährt.","coreRule":"⚡ Antworte auf das Gefühl, nicht auf den Köder.","beleg":"Werkstück H.2.1 (Die Geschichte, Reaktion B; Technik 1: Gefühle validieren; Der Kipppunkt: Deeskalation ist keine Unterwerfung; Kontext & Tiefe: Fakten-Argument im Feuer)","status":"entwurf","kurz":"Im Streit ist das Gegenüber emotional aufgewühlt und Argumente kommen kaum an. Wer das Gefühl hinter dem Vorwurf benennt und nachfragt, nimmt dem Streit Energie, ohne dem Inhalt zuzustimmen oder zurückzuschlagen.","prueffrage":"Wie laut und wie sachlich spricht dein Gegenüber gerade, und wie viel von dem, was du sagst, kommt in diesem Zustand bei ihm an?","rueckmeldung":[{"option":0,"text":"Nachzugeben beendet den Streit schnell und fühlt sich nach Frieden an. Du stimmst aber einer Aussage zu, die du selbst nicht teilst. Das ist Unterwerfung: Ein Gefühl ernst zu nehmen heißt nicht, den Inhalt zu bestätigen."},{"option":1,"text":"Die pauschale Zuschreibung ist wirklich kein Argument, und Grenzen zu setzen ist legitim. Der Satz klingt aber nach Gegenvorwurf und kündigt Rückzug an. So geht es bald darum, wer sich falsch verhält, und das Gefühl dahinter bleibt unbeachtet."},{"option":3,"text":"Sachlich zu bleiben und Zahlen zu nennen wirkt vernünftig. Doch das „aber“ entwertet das Verständnis, die Unterstellung, er kenne die Studienlage nicht, ist ein neuer Vorwurf, und Zahlen kommen in so einer Lage kaum an."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, Cook, Ecker u. a. (2020): The Debunking Handbook 2020 (doi 10.17910/b7.1182; geöffnet als PDF bei Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"9","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-035","clusterId":"H","werkstueckRef":"H.2.1","stufe":2,"question":"Dein Onkel hat beim Familienfest gerade behauptet, die Impfstudien seien alle gekauft. Du willst widersprechen, ohne dass er sofort in die Verteidigung geht. Welche Formulierung beschreibt deine eigene Wahrnehmung, statt ihm etwas zuzuschreiben?","options":["„Du ignorierst ständig die Fakten, und das macht mich wütend, weil du dich einfach nicht belehren lässt.“","„Ich finde, du bist in dieser Frage einfach irrational und lässt dir von niemandem etwas sagen.“","„Man sieht doch, dass die Fakten gegen dich sprechen, das müsste inzwischen wirklich jedem klar sein.“","„Die Studien, die ich bisher gesehen habe, deuten für mich in eine andere Richtung. Das verwirrt mich.“"],"correctIndex":3,"explanation":"Eine Aussage, die deine eigene Wahrnehmung beschreibt, ist eine persönliche Zustandsbeschreibung: Sie ist unangreifbar und lädt zur Klärung ein. Wer dem anderen dagegen eine Eigenschaft zuschreibt („du ignorierst“, „du bist irrational“), erhebt eine Anklage, auch wenn ein „ich“ im Satz steht („Ich finde, du bist …“). Das gilt auch für „Man sieht doch …“: Der Vorwurf steckt nur in einem unpersönlichen „man“. Auch ein Gefühl wie Wut ändert nichts daran, dass der erste Satz dem Onkel eine Eigenschaft zuschreibt. Solche Anklagen zwingen das Gegenüber in eine Verteidigungshaltung. Eskaliert ein Gespräch, geht es nur noch um Gewinnen und Verlieren. Eine Aussage über dein eigenes Erleben dagegen greift ihn nicht an.","coreRule":"⚡ Prüfe nicht, ob „ich“ im Satz steht, sondern ob du beschreibst, was bei dir ankommt, oder sagst, was der andere ist.","beleg":"Werkstück H.2.1 (Die Taktische Matrix: Technik 2, „Ich“-Botschaften)","status":"entwurf","scenario":"Beim Familienfest wird die Stimmung hitzig. Dein Onkel sagt laut: „Die Impfstudien sind doch alle von der Industrie gekauft!“ Du willst dagegenhalten, aber das Gespräch nicht noch weiter anheizen.","kurz":"Wer beschreibt, was er selbst wahrnimmt, etwa dass die gesehenen Studien für ihn in eine andere Richtung deuten und ihn das verwirrt, macht eine unangreifbare Aussage und lädt zum Klären ein. Zuschreibungen an den Onkel wirken als Anklage, auch mit „ich“ davor.","prueffrage":"Worüber sagt der Satz etwas aus: über das, was du erlebst, oder über die Person, der du antwortest?","rueckmeldung":[{"option":0,"text":"Dass dich das wütend macht, ist ein echtes Gefühl und darf gesagt werden. Doch davor steht „Du ignorierst ständig die Fakten“, und das ist eine Zuschreibung an den Onkel, auf die er sich vermutlich verteidigen wird."},{"option":1,"text":"„Ich finde“ klingt nach einer persönlichen Aussage, im Satz steht dann aber doch eine Eigenschaft des Onkels. „Du bist irrational“ bleibt eine Anklage, auch mit „ich“ davor, und lädt kaum zum Gespräch ein."},{"option":2,"text":"Auf Fakten zu verweisen ist völlig in Ordnung. Das unpersönliche „man“ verpackt hier aber einen Vorwurf: Es heißt, jedem sei es klar, und damit zugleich, dass der Onkel es trotzdem nicht sieht. Das setzt ihn unter Druck."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Rogers, Howieson & Neame (2018): I understand you feel that way, but I feel this way: the benefits of I-language and communicating perspective during conflict. PeerJ 6:e4831","oeffentlich":true,"doi":"10.7717/peerj.4831","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5961625/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-036","clusterId":"H","werkstueckRef":"H.2.1","stufe":3,"question":"Welche der vier Reaktionen sorgt zwar für Ruhe, gibt dafür aber eine falsche Behauptung preis?","scenario":"Dein Onkel behauptet am Familientisch, Echsenmenschen kontrollierten die Regierung, und wird dabei immer lauter. Du willst verhindern, dass der Abend eskaliert.","options":["„Ich merke, wie sehr dich das Thema beschäftigt. Inhaltlich sehe ich es anders, aber ich höre dir zu.“","„Na gut, vielleicht ist da was dran. Hauptsache, wir haben heute Abend Frieden.“","„Ich merke, wir drehen uns im Kreis. Lass uns morgen mit frischem Kopf weiterreden; mir ist das Gespräch wichtig.“","„Uns beiden liegt das Wohl der Familie am Herzen. Über den Weg dorthin denken wir nur unterschiedlich.“"],"correctIndex":1,"explanation":"Beruhigen und zustimmen sind zwei verschiedene Dinge. Du kannst das Gefühl deines Gegenübers anerkennen, eine Pause vorschlagen oder eine gemeinsame Absicht benennen, ohne dabei die Sachbehauptung gelten zu lassen. Dein Onkel erfährt in diesen Fällen: Ich nehme dich ernst, aber ich teile deine Aussage nicht. „Vielleicht ist da was dran“ dagegen signalisiert Zustimmung zu einer unbelegten Behauptung, nur um Ruhe zu haben. Der Frieden wird damit mit einer Unwahrheit erkauft, und der Onkel fühlt sich in seiner Überzeugung bestätigt. Deeskalieren soll das Gespräch offenhalten, nicht die eigene Position aufgeben.","coreRule":"⚡ Gefühle darfst du bestätigen, falsche Behauptungen nicht.","beleg":"Werkstück H.2.1 (Der Kipppunkt; Die Taktische Matrix)","status":"entwurf","kurz":"Beruhigen heißt nicht zustimmen: „Vielleicht ist da was dran“ erkauft den Frieden mit einer Unwahrheit und bestärkt den Onkel. Gefühl anerkennen, Pause vorschlagen oder Gemeinsames betonen beruhigt ebenfalls, lässt die Behauptung aber nicht gelten.","prueffrage":"Was erfährt dein Onkel über deine Sicht auf seine Behauptung, wenn er nur deine Antwort hört?","rueckmeldung":[{"option":0,"text":"Hier bleibt die Ruhe nicht auf Kosten der Wahrheit: Du erkennst sein Gefühl an und sagst offen, dass du es inhaltlich anders siehst. Deine Position gibst du damit nicht auf."},{"option":2,"text":"Eine Pause vorzuschlagen wirkt vielleicht wie Ausweichen, ist aber echte Deeskalation: Du stimmst der Behauptung nicht zu und sagst dem Onkel zugleich, dass dir das Gespräch wichtig ist. Das Thema bleibt offen."},{"option":3,"text":"Die gemeinsame Absicht zu betonen, beruhigt, ohne der Sachbehauptung zuzustimmen. Der Satz räumt ausdrücklich ein, dass ihr unterschiedlich denkt. Du gibst also nichts preis, was du nicht preisgeben willst."}],"familie":"gefuehl-zuerst-aufgreifen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-037","clusterId":"H","werkstueckRef":"H.2.2","stufe":1,"question":"Du sprichst mit einer Kollegin, die fest überzeugt ist, dass ihr Wundermittel gegen Migräne hilft. Du willst herausfinden, wie sie zu dieser Überzeugung gekommen ist, ohne sie anzugreifen. Welche Frage hilft dir, ihre Überzeugung genauer zu fassen und die Methode dahinter zu klären?","options":["„Wie sicher bist du auf einer Skala von 0 bis 100, und was ist der Hauptgrund für diese Einschätzung?“","„Wie intelligent schätzt du dich selbst ein, wenn es um medizinische Fragen geht?“","„Wie viele Studien kannst du mir nennen, bevor ich deine Aussage ernst nehmen muss?“","„Wie hoch ist deine Sicherheit, und stimmst du mir zu, wenn du die Zahl nennst?“"],"correctIndex":0,"explanation":"„Absolut sicher“ ist ein Entweder-oder, über das sich schlecht reden lässt. Eine Skala von 0 bis 100 macht daraus ein flexibles Spektrum, an dem man gemeinsam ansetzen kann: Warum 95 und nicht 60? Die anschließende Frage nach dem Hauptgrund deckt die Methode auf, auf der die Sicherheit beruht (zum Beispiel eigene Erfahrung oder ein Tipp einer Freundin). Genau diese Methode lässt sich dann auf ihre Verlässlichkeit prüfen, ohne dass du die Schlussfolgerung angreifst. Die anderen Fragen scheitern an je einem Punkt: Die Frage nach der Intelligenz wertet die Person ab, statt ihre Methode zu klären. Die Forderung nach Studien greift die Schlussfolgerung mit Fakten an, statt die Methode zu erkunden. Die Zahl als Falle zu benutzen, ist unehrlich: Ohne echte Neugier spürt dein Gegenüber das Kreuzverhör sofort.","coreRule":"⚡ Frag erst nach dem Grad der Sicherheit, dann nach dem Grund dafür, nicht nach dem Urteil.","beleg":"Werkstück H.2.2 (Kontext & Tiefe: Schritte 3 und 4, 6)","status":"entwurf","scenario":"Deine Kollegin sagt: „Ich bin mir absolut sicher, dass dieses Mittel gegen Migräne hilft.“ Du möchtest weder streiten noch sofort Studien auf den Tisch legen, sondern verstehen, worauf ihre Sicherheit beruht.","kurz":"Eine Skala von 0 bis 100 macht aus „absolut sicher“ ein Spektrum, über das ihr reden könnt, und die Frage nach dem Hauptgrund legt offen, worauf die Sicherheit beruht. So prüfst du ihre Methode, ohne ihre Schlussfolgerung anzugreifen.","prueffrage":"Was hat deine Kollegin bisher tatsächlich gesagt: Nennt sie einen Grund für ihre Sicherheit oder nur die Sicherheit selbst?","rueckmeldung":[{"option":1,"text":"Wie sie zu ihrer Überzeugung kam, erfährst du so nicht, denn gefragt wird nach ihr als Person und nicht nach dem Weg. Das klingt schnell nach Abwertung und macht das Gespräch eher defensiv."},{"option":2,"text":"Belege sind später durchaus wichtig. Die Frage greift die Schlussfolgerung aber mit Fakten an und unterstellt, die Überzeugung müsse auf Studien beruhen. Dabei wolltest du erst verstehen, worauf sie tatsächlich beruht."},{"option":3,"text":"Eine Zahl zur Sicherheit zu erfragen, ist ein guter Anfang. Doch der Zusatz macht sie zur Falle, mit der du Zustimmung holen willst. Das Gegenüber spürt das Kreuzverhör, und der Grund hinter der Zahl bleibt unerkundet."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: Using a Confidence Scale in Street Epistemology (31.05.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m08-using-a-confidence-scale-in-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-h-038","clusterId":"H","werkstueckRef":"H.2.2","stufe":2,"question":"Welche Anschlussfrage ist dafür am besten geeignet?","scenario":"Ein Kollege ist zu 95 Prozent sicher, dass Rosenquarz Kopfschmerzen heilt. Seine Begründung: Eine Freundin hat es empfohlen, und bei ihm selbst hörten die Beschwerden danach auf. Du möchtest mit ihm ins Gespräch kommen, ohne dass er sich angegriffen fühlt, und ihm helfen, die Verlässlichkeit seiner Begründung selbst zu prüfen.","options":["„Das ist längst widerlegt: Kristalle wirken nicht über den Placebo-Effekt hinaus. Wie kannst du da noch so sicher sein?“","„Du glaubst wohl alles, was Freundinnen dir erzählen. Hast du nie überlegt, wie leicht man sich täuschen lässt?“","„Wenn du dir so sicher bist, dann nenn mir doch bitte drei Studien, die das belegen. Welche sind es genau?“","„Du verlässt dich also auf deine Erfahrung. Wie ließe sich prüfen, ob wirklich der Kristall geholfen hat? Welcher Weg wäre am verlässlichsten?“"],"correctIndex":3,"explanation":"Wer die Überzeugung eines Menschen direkt angreift, löst meist Abwehr aus, und mit Abwehr endet das Nachdenken. Besser ist es, zuerst zu verstehen, worauf sich die Sicherheit stützt, und dann gemeinsam zu prüfen, ob dieser Weg verlässlich ist. Hier ist die Begründung eine einzelne Erfahrung: Die Kopfschmerzen hörten nach dem Kristall auf. Das passt aber ebenso zum Placebo-Effekt oder dazu, dass sie von allein vergangen wären. Die Frage, wie man das auseinanderhalten könnte, lädt zum Mitdenken ein, ohne ein Urteil zu fällen. Die Faktenbehauptung wirkt wie ein Frontalangriff. Die Frage nach den Freundinnen greift die Person an, statt ihre Begründung zu prüfen. Die Forderung nach Studien wirkt wie ein Kreuzverhör, und das Gegenüber merkt schnell, wenn Neugier nur gespielt ist.","coreRule":"⚡ Frag nach dem Weg zur Überzeugung und lade zum gemeinsamen Prüfen ein, statt das Ergebnis anzugreifen.","beleg":"Werkstück H.2.2 (Die Geschichte, Ansatz B; Kontext & Tiefe: Schritt 5; Red Flags)","status":"entwurf","kurz":"Eine Frage, die seine Erfahrung ernst nimmt und fragt, wie sich prüfen ließe, ob wirklich der Kristall half, lädt zum Mitdenken ein, denn auch Placebo oder ein von selbst endender Schmerz passen dazu. Ein direkter Angriff löst dagegen meist Abwehr aus.","prueffrage":"Worauf stützt dein Kollege seine 95 Prozent, und welche Anschlussfrage knüpft an genau diese Stütze an?","rueckmeldung":[{"option":0,"text":"Inhaltlich liegst du mit dem Placebo-Hinweis richtig, aber als fertiges Urteil mit „Wie kannst du da noch so sicher sein?“ klingt es nach Angriff. Meist folgt darauf Abwehr, und dann hört dein Kollege nicht mehr zu."},{"option":1,"text":"Eine Empfehlung als Quelle zu hinterfragen, kann sinnvoll sein. Die Frage zielt aber auf die Person („glaubst wohl alles“) statt auf die Begründung und lässt ihn kaum mit Neugier antworten, eher mit Rechtfertigung."},{"option":2,"text":"Nach Belegen zu fragen ist grundsätzlich legitim. Mit „drei Studien, welche genau“ wirkt es aber wie ein Kreuzverhör, und seine Begründung ist ohnehin eine eigene Erfahrung. Spielt man Neugier nur, merkt das Gegenüber das schnell."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Boghossian, P. (2013): A Manual for Creating Atheists. Pitchstone Publishing (Begriffsprägung; Register b7b36492df7, sekundär bestätigt)","oeffentlich":false}],"thema":"Gesundheit"},{"id":"qx-h-039","clusterId":"H","werkstueckRef":"H.2.2","stufe":3,"question":"Wobei bringt dir eine Reihe offener Fragen zur Methode deines Gegenübers am wenigsten?","options":["Jemand behauptet, Paris sei die Hauptstadt von Deutschland, und beruft sich dabei auf eine vage Erinnerung an eine Schulstunde vor vielen Jahren.","Jemand ist zu 90 Prozent sicher, dass seine Intuition ihm den richtigen Beruf zeigt, und bleibt trotz eigener Zweifel bei dieser Überzeugung.","Jemand hält Horoskope für absolut zutreffend und erzählt dir ausführlich, wie sehr ihm das im Leben hilft und wie sicher er sich ist.","Jemand hat vor Kurzem in einer Gruppe ein Weltbild übernommen und verteidigt es mit viel Gefühl und mit nur wenigen echten Belegen."],"correctIndex":0,"explanation":"Fragen nach der Methode lohnen sich bei tiefen, identitätsstiftenden Überzeugungen: Hier steht die Zuverlässigkeit des Wegs zur Überzeugung im Mittelpunkt, und genau das lässt sich gemeinsam erkunden. Bei einer reinen Tatsachenfrage wie der nach der Hauptstadt Deutschlands ist eine sokratische Befragung dagegen meist überflüssig; hier genügt eine einfache Richtigstellung.","coreRule":"⚡ Faktenfragen beantwortest du, Überzeugungen erkundest du.","beleg":"Werkstück H.2.2 (Red Flags: Wann man SE nicht anwenden sollte)","status":"entwurf","scenario":"Du sprichst mit vier Menschen, die jeweils etwas behaupten.","quote":"","quoteLabel":"","kurz":"Offene Fragen zur Methode lohnen sich, wo der Weg zur Überzeugung selbst zählt. Bei einer schlichten Tatsache wie der Hauptstadt Deutschlands sind sie meist überflüssig, hier genügt eine Richtigstellung. Nicht jede Behauptung ist eine Weltanschauung.","prueffrage":"Wie viel hängt für jeden der vier Menschen an seiner Behauptung, und was ginge ihm verloren, wenn er sich irrte?","rueckmeldung":[{"option":1,"text":"Hier lohnen sich offene Fragen gerade: Wie verlässlich ist Intuition als Weg zur Berufswahl, und woher kommen die Zweifel? Daran lässt sich gemeinsam arbeiten, anders als bei einer einfach nachprüfbaren Tatsache."},{"option":2,"text":"Auch beim Horoskop lohnt die Frage nach dem Weg zur Überzeugung: Woran würde die Person merken, dass es nicht zutrifft? Wie jemand zu so einer Gewissheit kommt, bietet genug Stoff für ein offenes Gespräch."},{"option":3,"text":"Ein Weltbild mit viel Gefühl und wenig Belegen ist genau der Fall, in dem Fragen nach Herkunft und Prüfbarkeit weiterhelfen. Behutsam gestellt, öffnen sie das Gespräch, statt es zu verengen."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, Cook, Ecker u. a. (2020): The Debunking Handbook 2020 (doi 10.17910/b7.1182; geöffnet als PDF bei Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/DebunkingHandbook2020.pdf","seite":"9","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-040","clusterId":"H","werkstueckRef":"H.2.2","stufe":4,"question":"Welche Frage bringt ihn am ehesten dazu, selbst zu prüfen, wie belastbar seine Überzeugung ist?","scenario":"Ein Kollege sagt dir im Gespräch: „Ich bin zu 95 % sicher, dass Heilkristalle Krankheiten heilen. Meine Kopfschmerzen sind verschwunden, als ich einen Rosenquarz benutzt habe, und eine Freundin schwört auch darauf.“ Du willst ihn nicht belehren, sondern ihn zum Nachdenken über seine eigene Überzeugung bringen, ohne dass er sich angegriffen fühlt.","options":["„Studien zeigen längst, dass Kristalle nicht wirken. Warum glaubst du trotzdem noch daran?“","„Wie bist du zu dieser Überzeugung gekommen, und wie verlässlich ist dieser Weg?“","„Findest du es nicht naiv, einer Freundin mehr zu glauben als der Medizin?“","„Gibst du zu, dass du dich geirrt hast, wenn es auch ohne Kristall verschwunden wäre?“"],"correctIndex":1,"explanation":"Wer eine tief gehaltene Überzeugung frontal widerlegt, macht sein Gegenüber defensiv, und das Gespräch endet. Wirksamer ist es, nicht die Schlussfolgerung („Kristalle heilen nicht“) anzugreifen, sondern das Verfahren zu untersuchen, mit dem die Person dorthin gekommen ist: Worauf stützt sich die Sicherheit, und kann dieser Weg auch zu falschen Ergebnissen führen? Hier ist der Weg die persönliche Erfahrung („Kopfschmerzen sind verschwunden“). Ob sie verlässlich ist, lässt sich gemeinsam fragen: Wäre der Schmerz vielleicht auch von allein vergangen, oder spielt der Placebo-Effekt eine Rolle? Die erste Frage trägt Fakten vor und setzt auf Autorität statt auf eigene Prüfung. Die dritte wertet die Person und ihre Freundin ab. Die vierte verlangt ein Eingeständnis und wirkt wie ein Kreuzverhör; den Verhörton spürt das Gegenüber sofort. All das erzeugt Abwehr statt Nachdenken.","coreRule":"⚡ Frag nach der Methode, nicht nach der Schlussfolgerung.","beleg":"Werkstück H.2.2 (Street Epistemology); Fn. gl-h-4 (Boghossian 2013, A Manual for Creating Atheists)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer eine tiefe Überzeugung frontal widerlegt, erzeugt Abwehr. Besser ist, den Weg dorthin gemeinsam zu betrachten: Worauf stützt sich die Sicherheit, und kann dieser Weg auch zu falschen Ergebnissen führen?","prueffrage":"Welche Gründe nennt dein Kollege selbst für seine 95 Prozent, und welche davon hat er selbst erlebt?","rueckmeldung":[{"option":0,"text":"Der Hinweis auf die Studienlage ist sachlich zutreffend. Als Frage verpackt, bleibt er aber ein Vortrag, der Autorität an die Stelle eigener Prüfung setzt, und das „trotzdem noch“ klingt wie ein Vorwurf, der eher Verteidigung auslöst."},{"option":2,"text":"Das Wort „naiv“ wertet den Kollegen und seine Freundin ab, und die Frage stellt sie gegen „die Medizin“. Sie untersucht nicht, wie seine Sicherheit entstanden ist, und erzeugt eher Abwehr als Nachdenken."},{"option":3,"text":"Die Überlegung dahinter trägt: Der Schmerz könnte tatsächlich von allein vergangen sein. Als Aufforderung zum Eingeständnis klingt die Frage aber nach Kreuzverhör, und dann verteidigt sich dein Kollege, statt nachzudenken."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Street Epistemology International: What Is Street Epistemology? A Beginner's Introduction (12.04.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m01-what-is-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Street Epistemology International: Using a Confidence Scale in Street Epistemology (31.05.2026)","oeffentlich":true,"url":"https://www.streetepistemology.com/blog/nb-m08-using-a-confidence-scale-in-street-epistemology","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-h-041","clusterId":"H","werkstueckRef":"H.2.3","stufe":1,"question":"Was ist am Vorgehen von Jonas in diesem Gespräch das Problem?","options":["Jonas hört nur so lange zu, bis er einen Punkt zum Widerlegen gefunden hat. Was Mehmet meint und fühlt, bleibt ungeklärt, und genau das nimmt Mehmet wahr.","Jonas bringt zu wenig eigene Erfahrungen ein. Wer dem Gegenüber zeigt, dass er Ähnliches erlebt hat, wirkt glaubwürdiger und überzeugt dadurch schneller.","Jonas stellt zu viele Rückfragen. Ein Gespräch gewinnt an Tiefe, wenn man schweigend alles aufnimmt und den Redefluss nicht durch Nachhaken stört.","Jonas merkt sich Mehmets Argumente nicht genau genug. Wer jedes Detail im Kopf behält, kann später gezielter und lückenloser kontern."],"correctIndex":0,"explanation":"Jonas hört nur scheinbar zu: Die Worte laufen durch seine eigene Agenda, während der Kopf schon die Widerlegung baut. Damit bleibt offen, was Mehmet eigentlich sagen will und was ihn antreibt, etwa Sorge oder Misstrauen. Verstehen entsteht eher, wenn man die Aussage in eigenen Worten zurückgibt, Gefühle benennt, offen nachfragt und Ablenkungen wie das Handy weglässt; erst dann lässt sich prüfen, worüber man überhaupt streitet. Eigene Geschichten lenken die Aufmerksamkeit dagegen auf einen selbst, und klärende Rückfragen sind keine Störung, sondern zeigen, ob man richtig verstanden hat. Wer Argumente nur sammelt, um sie zu widerlegen, hört weiterhin nur durch die eigene Agenda.","coreRule":"⚡ Hör zu, um zu verstehen, nicht um zu antworten.","quote":"","quoteLabel":"","beleg":"Werkstück H.2.3 (Kernidee; Kontext & Tiefe; Werkbank-Frage)","status":"entwurf","scenario":"Jonas' Schwager Mehmet erzählt aufgebracht, dass er nach der Impfung seiner Tochter ernste Zweifel an Medizin und Behörden habe. Jonas nickt, schaut aber nebenbei auf sein Handy und überlegt schon, mit welchen Studien er gleich alles widerlegen kann. Als Mehmet Luft holt, setzt Jonas sofort an: „Das ist alles längst widerlegt, und zwar so …“ Mehmet winkt ab und sagt: „Du hörst mir gar nicht zu.“","kurz":"Jonas hört nur durch seine eigene Agenda zu und baut im Kopf schon die Widerlegung. So bleibt offen, was Mehmet meint und was ihn antreibt, etwa Sorge oder Misstrauen, und genau das spürt Mehmet.","prueffrage":"Was tut Jonas, während Mehmet spricht, und was tut er, sobald Mehmet Luft holt?","rueckmeldung":[{"option":1,"text":"Wer von eigenen Erfahrungen erzählt, schafft manchmal Nähe. Der Aufmerksamkeitsfokus wandert dabei aber zu einem selbst, und Mehmets Anliegen bleibt unverstanden. Jonas' Problem ist nicht zu wenig Eigenes, sondern zu wenig Zuhören."},{"option":2,"text":"Klärende Rückfragen sind keine Störung, sie gehören zum Zuhören: Sie zeigen, ob man richtig verstanden hat. Jonas stellt keine einzige, er wartet nur auf den Moment, in dem er widersprechen kann."},{"option":3,"text":"Alle Argumente genau zu behalten, klingt gründlich. Sie nur zu sammeln, um sie zu widerlegen, ist aber weiterhin Zuhören durch die eigene Agenda. Was Mehmet antreibt, etwa Sorge oder Misstrauen, wird so nicht klarer."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kalla & Broockman (2020): Reducing Exclusionary Attitudes through Interpersonal Conversation: Evidence from Three Field Experiments (APSR 114(2), doi 10.1017/S0003055419000923; frei als SocArXiv-Vorabfassung vom 17.01.2020)","oeffentlich":true,"doi":"10.31235/osf.io/2ra9x","seite":"Abstract (S. 1 der Vorabfassung)","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-042","clusterId":"H","werkstueckRef":"H.2.3","stufe":2,"question":"Welche deiner möglichen Antworten erreicht das am besten?","scenario":"Dein Freund erzählt dir seit einigen Minuten, wie sehr ihn ein Streit mit seiner Chefin beschäftigt. Er sagt: „Ich habe ihr gestern gesagt, dass ich so nicht weiterarbeiten will, und sie hat nur gesagt, das sei kein guter Zeitpunkt. Ich komme mir vor, als wäre ich ihr egal.“ Du willst, dass er sich verstanden fühlt und dass du selbst sicher bist, ihn richtig verstanden zu haben.","options":["„Das kenne ich gut: Bei mir war das damals genauso, ich habe einfach gekündigt und es nie bereut. Das war die beste Entscheidung meines Lebens.“","„An deiner Stelle würde ich gleich morgen das Gespräch mit ihr suchen, klare Bedingungen stellen und danach nicht mehr nachgeben.“","„Findest du nicht auch, dass sie sich längst bei dir hätte entschuldigen müssen, nachdem sie dich so einfach abgewiesen hat?“","„Wenn ich dich richtig verstehe, ärgert dich vor allem, dass sie dein Anliegen abgetan hat. Du fühlst dich nicht ernst genommen. Stimmt das so?“"],"correctIndex":3,"explanation":"Du willst zwei Dinge erreichen: Er soll sich verstanden fühlen, und du willst wissen, ob dein Bild von seiner Lage stimmt. Das gelingt, wenn du in eigenen Worten wiedergibst, was du gehört hast, und ihm die Chance gibst, dich zu korrigieren. So ist dein Verständnis geprüft, bevor du irgendetwas bewertest oder rätst. Die eigene Geschichte stellt dich in den Mittelpunkt, und der Ratschlag kommt, bevor klar ist, was ihn beschäftigt; beide prüfen nicht, ob du ihn verstanden hast. Die Suggestivfrage legt ihm ein Urteil in den Mund, statt zu klären, was ihn tatsächlich bewegt.","coreRule":"⚡ Gib zurück, was du gehört hast, und frag, ob es stimmt.","beleg":"Werkstück H.2.3 (Technik 1: Paraphrasieren; Red Flags; Werkbank-Frage)","status":"entwurf","kurz":"Wenn du in eigenen Worten wiedergibst, was du gehört hast, und ihn korrigieren lässt, prüfst du dein Verständnis, bevor du bewertest oder rätst. Der naheliegende Fehler ist, sofort zu antworten, statt zu klären, ob du ihn richtig verstanden hast.","prueffrage":"Was von dem, was der Freund gesagt hat, kannst du wörtlich belegen, und was hast du bisher nur selbst dazugedacht?","rueckmeldung":[{"option":0,"text":"Eine eigene Erfahrung kann Nähe schaffen und gut gemeint sein. Hier lenkt sie das Gespräch aber auf dich und rät ganz nebenbei zur Kündigung, ohne dass klar wäre, ob du seine Lage richtig erfasst hast."},{"option":1,"text":"Ein Rat zeigt, dass dir sein Problem nicht gleichgültig ist. Er kommt aber, bevor feststeht, was ihn eigentlich beschäftigt, und prüft nicht, ob dein Bild von der Lage stimmt. So bleibt offen, ob er sich gehört fühlt."},{"option":2,"text":"Die Frage greift seinen Ärger auf und wirkt deshalb solidarisch. Sie legt ihm aber ein Urteil in den Mund: Von einer Entschuldigung hat er nichts gesagt. So klärst du nicht, was ihn bewegt, sondern lenkst ihn in eine Richtung."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-043","clusterId":"H","werkstueckRef":"H.2.3","stufe":3,"question":"Was ist jetzt der beste nächste Schritt?","scenario":"Du streitest mit deiner Schwester über die Pflege eurer Mutter. Du bist überzeugt, dass sie sich zu wenig kümmert. Bevor du deinen Standpunkt darlegst, willst du sicherstellen, dass du ihre Sicht wirklich verstanden hast, und fasst sie zusammen: „Du sagst also, dass du dich überfordert fühlst und dir von mir mehr Anerkennung wünschst.“ Sie antwortet: „Na ja, so ungefähr.“","options":["Du gehst davon aus, dass „so ungefähr“ genügt, und erklärst nun deinen eigenen Standpunkt, denn sie hat deine Zusammenfassung nicht zurückgewiesen.","Du fragst nach, was an deiner Zusammenfassung noch nicht stimmt, und fasst ihren Standpunkt neu zusammen, bis sie ihn als zutreffend bestätigt.","Du betonst, dass du ihre Sicht nachvollziehen kannst, und wechselst dann zu deinem Anliegen, damit das Gespräch nicht stockt.","Du stimmst ihr in einem Punkt ausdrücklich zu, damit sie sich ernst genommen fühlt, und legst dann deinen Standpunkt dar."],"correctIndex":1,"explanation":"Ein halbherziges „so ungefähr“ ist kein Zeichen, dass du sie verstanden hast. Es zeigt eher, dass noch etwas fehlt oder verzerrt ist. Wer jetzt weiterredet, antwortet auf ein Bild von ihr, das sie selbst nicht teilt, und sie fühlt sich weiter missverstanden. Erst wenn sie deine Zusammenfassung aus eigener Sicht als zutreffend bestätigt, etwa mit „Ja, genau“, weißt du, dass ihre Position richtig bei dir angekommen ist. Dafür musst du ihr nicht zustimmen: Verstehen ist nicht Einverstandensein. Es reicht, ihren Standpunkt so zu fassen, dass sie ihn als ihren erkennt. Das Nachfragen kostet anfangs Zeit, verändert aber die Dynamik des Gesprächs, weil sie spürt, dass du ihre Sicht ernsthaft erfassen willst.","coreRule":"⚡ Erst wenn der andere sagt „Ja, genau“, bist du an der Reihe.","beleg":"Werkstück H.2.3 (Die Schmiede-Übung: Die Papageien-Regel)","status":"entwurf","kurz":"„So ungefähr“ ist noch kein „Ja, genau“: Etwas fehlt oder ist verzerrt. Wer jetzt weiterredet, antwortet auf ein Bild von ihr, das sie nicht teilt. Erst wenn sie deine Zusammenfassung als ihre erkennt, hast du sie verstanden.","prueffrage":"Welche Teile deiner Zusammenfassung hat deine Schwester ausdrücklich aufgegriffen oder bestätigt?","rueckmeldung":[{"option":0,"text":"Dass sie nicht widersprochen hat, wirkt wie Einverständnis. Ein halbherziges „so ungefähr“ ist aber keine Bestätigung, sondern deutet auf etwas Fehlendes oder Verzerrtes, und dein Standpunkt träfe auf ein Bild, das sie nicht teilt."},{"option":2,"text":"Ihre Sicht nachvollziehen zu können ist ein guter Ton, und dafür musst du ihr nicht zustimmen. Nur ist noch gar nicht geklärt, ob du sie richtig erfasst hast. Mit dem Themenwechsel bleibt das Ungefähre stehen, und sie fühlt sich weiter nicht gesehen."},{"option":3,"text":"Ausdrückliche Zustimmung zeigt Wertschätzung, doch Verstehen verlangt sie nicht. Entscheidend ist, ob sie deine Zusammenfassung als ihre erkennt. Das ist offen, und stimmst du einem womöglich schiefen Bild zu, festigst du das Missverständnis."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-044","clusterId":"H","werkstueckRef":"H.2.3","stufe":4,"question":"Welche Antwort setzt aktives Zuhören um, wenn dein Ziel ist, dass das Gespräch mit Alex weitergeht?","scenario":"Alex, ein alter Freund, meldet sich nach Monaten: Er schlafe kaum, analysiere nachts „Drops“ und habe Angst um alle, die „es nicht sehen“. Er schreibt: „Manchmal denke ich, ich werde verrückt. Du hältst mich wahrscheinlich für einen Idioten.“","options":["„Danke, dass du dich meldest. Ich höre, dass du kaum schläfst und Angst hast. Ich halte dich nicht für einen Idioten. Magst du erzählen, was dich nachts am meisten beunruhigt?“","„Schön, von dir zu hören. Ich mache mir Sorgen, weil du dich da in etwas verrennst. Das ist nachweislich falsch, deshalb schicke ich dir gleich drei Faktenchecks dazu.“","„Danke für dein Vertrauen. Ich verstehe deine Angst vollkommen, auch ich sehe, dass die Medien vieles verschweigen. Gemeinsam schaffen wir das, du bist damit nicht allein.“","„Schön, dass du dich meldest. Ich möchte mit dir reden, aber vorher versprich mir bitte, dass du nachts nicht mehr recherchierst, sonst kann ich dir nicht helfen.“"],"correctIndex":0,"explanation":"Wer verstehen will, was jemand erlebt, nimmt zuerst auf, was er sagt und fühlt: das Gefühl benennen (Angst, Erschöpfung), das Gehörte in eigenen Worten wiedergeben und offen nachfragen. Das hält die Tür offen und liefert dir die Informationen, die du für jedes weitere Gespräch brauchst. Wer sofort mit Faktenchecks widerlegt, antwortet auf den Inhalt und überhört den Menschen. Wer die Behauptung der Medienverschwiegenheit mitträgt, bestätigt den Inhalt, ohne ihn verstanden oder geprüft zu haben, und verwechselt Mitgefühl mit Zustimmung. Wer Zuwendung an ein Versprechen knüpft, macht Nähe von einer Bedingung abhängig und beendet das Zuhören, bevor es begonnen hat. Du musst Alex nicht zustimmen, um ihn zu verstehen.","coreRule":"⚡ Biete Verbindung an, keine Korrektur: Hör zu, um zu verstehen, nicht um zu antworten.","beleg":"Werkstück H.2.3 (Techniken: Paraphrasieren, Emotionen benennen, klärende Fragen); Fn. gl-h-zuhoeren (Braun/Burian/Diefenbacher 2016; Wilke 1994; Kraft 2016). Buchbezug „im Sinne von H.2.3“ aus der Frage entfernt; Optionen auf gleiche Bauart und ähnliche Länge angeglichen (Option 3 hat kein Begründungsanhängsel mehr als die übrigen).","status":"entwurf","kurz":"Aktives Zuhören nimmt zuerst auf, was Alex fühlt und sagt: Angst und Erschöpfung benennen, in eigenen Worten wiedergeben, offen nachfragen. So bleibt das Gespräch offen. Wer sofort widerlegt oder zustimmt, hat den Menschen noch nicht gehört.","prueffrage":"Was schreibt Alex über sich selbst, und was befürchtet er am Ende seiner Nachricht?","rueckmeldung":[{"option":1,"text":"Die Sorge um Alex ist echt, und Faktenchecks können später ihren Platz haben. Als erste Antwort überhören sie aber Angst und Erschöpfung, und „nachweislich falsch“ klingt wie das Urteil, das Alex schon befürchtet."},{"option":2,"text":"Wärme und die Zusage, dass er nicht allein ist, tun Alex wohl. Doch wer bestätigt, die Medien verschwiegen vieles, stimmt einem ungeprüften Inhalt zu, verwechselt Mitgefühl mit Zustimmung und fragt nicht nach."},{"option":3,"text":"Der Wunsch zu reden und die Sorge um Alex' Schlaf sind gut gemeint. Wer Zuwendung an ein Versprechen knüpft, macht Nähe aber zur Bedingung. Alex wird dann kontrolliert statt gehört, und das Zuhören endet, bevor es angefangen hat."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Richmond, Berlin, Fishkind u. a. (2012): Verbal De-escalation of the Agitated Patient: Consensus Statement of the American Association for Emergency Psychiatry Project BETA De-escalation Workgroup. West J Emerg Med 13(1)","oeffentlich":true,"doi":"10.5811/westjem.2011.9.6864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3298202/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"10","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kalla & Broockman (2020): Reducing Exclusionary Attitudes through Interpersonal Conversation: Evidence from Three Field Experiments (APSR 114(2), doi 10.1017/S0003055419000923; frei als SocArXiv-Vorabfassung vom 17.01.2020)","oeffentlich":true,"doi":"10.31235/osf.io/2ra9x","seite":"Abstract (S. 1 der Vorabfassung)","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-045","clusterId":"H","werkstueckRef":"H.2.4","stufe":1,"question":"Welche Entscheidung ist hier die klügste?","options":["Das Gespräch ruhig beenden („Wir reden nicht mehr über die Sache, deshalb höre ich hier auf“), weil kein Austausch von Argumenten mehr stattfindet.","Weiterdiskutieren, bis er einlenkt („Ich gebe nicht auf“), weil die bisher investierte Stunde sonst umsonst gewesen wäre.","Das Gespräch abbrechen, indem du ihn beschimpfst („Mit dir ist nicht zu reden“), damit er merkt, dass du seine Taktik durchschaust.","Noch mehr Belege und Zahlen anführen („Dann zeige ich dir die Daten“), weil sich jemand mit genügend Fakten irgendwann überzeugen lässt."],"correctIndex":0,"explanation":"Ein Gespräch lebt davon, dass beide auf Argumente eingehen und eine gemeinsame Wirklichkeit anerkennen. Hier wird beides gebrochen: Er greift die Person statt der Sache an und leugnet, was er selbst gesagt hat. Solange das so bleibt, bringt jeder weitere Beitrag nichts, denn es geht ihm nicht mehr ums Überzeugen. Die bisher investierte Zeit ist kein Grund weiterzumachen, sondern eine versunkene Investition: Sie ist verloren, ob du aufhörst oder nicht, und weiteres Mitspielen kostet nur zusätzliche Kraft. Mehr Belege helfen nicht, wenn Gegenargumente ohnehin nicht zählen. Eine Beschimpfung wäre ein Kontrollverlust und würde ihm nützen. Ruhig und begründet auszusteigen schützt deine Energie und lässt dir die Souveränität.","coreRule":"⚡ Wer das Brett umwirft, spielt nicht mehr Schach: Dann darfst du aufstehen.","beleg":"Werkstück H.2.4 (Die Geschichte; Kernidee; Kontext & Tiefe; Anwendung & Relevanz – Wie man den Ausstieg vollzieht)","status":"entwurf","scenario":"Du diskutierst seit einer Stunde mit einem Bekannten über ein politisches Thema. Auf jede Gegenfrage antwortet er nur noch mit Angriffen auf deine Person („Du hast ja keine Ahnung“). Als du dich auf seine eigene Aussage von vorhin beziehst, behauptet er, das nie gesagt zu haben. Dein Versuch, zur Sache zurückzukehren, scheitert zum dritten Mal. Du bist erschöpft, und das Gespräch dreht sich seit Minuten im Kreis.","quote":"","quoteLabel":"","kurz":"Ruhig auszusteigen ist klug, weil er keine Argumente mehr gelten lässt und weitere Beiträge nichts bewirken. Der Denkfehler wäre, die bereits investierte Stunde zu retten, die verloren ist, ob du aufhörst oder nicht.","prueffrage":"Geht er mit seinen letzten Antworten noch auf das ein, was du sagst, oder nur auf dich als Person?","rueckmeldung":[{"option":1,"text":"Eine Stunde Einsatz fühlt sich an, als dürfe sie nicht umsonst gewesen sein. Sie ist aber ohnehin verloren, ob du aufhörst oder nicht, und weiteres Mitspielen kostet nur zusätzliche Kraft."},{"option":2,"text":"Dass du seine Taktik durchschaust, stimmt, und der Ärger ist verständlich. Eine Beschimpfung bedeutet aber Kontrollverlust und nützt ihm, weil sie dich auf sein Niveau zieht und dir die Souveränität nimmt."},{"option":3,"text":"Fakten überzeugen nur, wenn Gegenargumente überhaupt zählen. Wer dich persönlich angreift und eigene Aussagen leugnet, lässt Zahlen nicht gelten; weitere Belege prallen ab wie deine drei Versuche, zur Sache zurückzukehren."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Petrov, Chan, Lau u. a. (2023): Sunk Cost Effects for Time Versus Money: Replication and Extensions Registered Report of Soman (2001). International Review of Social Psychology 36(1), Art. 17","oeffentlich":true,"doi":"10.5334/irsp.883","url":"https://rips-irsp.com/articles/10.5334/irsp.883","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansen, H. (2015/2024): Fallacies. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Arkes & Blumer (1985): The Psychology of Sunk Cost. Organizational Behavior and Human Decision Processes 35(1) (nicht frei, laut OpenAlex geschlossen; in Landkarte B.6 geprüft)","oeffentlich":false,"doi":"10.1016/0749-5978(85)90049-4"}],"thema":"Zusammenleben"},{"id":"qx-h-046","clusterId":"H","werkstueckRef":"H.2.4","stufe":2,"question":"Welcher Abschlusssatz beendet das Gespräch in dieser Lage am besten?","scenario":"Dein Gegenüber wirft dir seit einer Weile Halbwahrheiten im Minutentakt hin, geht auf keinen deiner Punkte ein und wird persönlich. Zwei Versuche, das Gespräch zu beruhigen und zur Sache zurückzuführen, sind gescheitert. Du merkst, dass dich jede weitere Antwort nur Kraft kostet, ohne dass etwas geklärt wird.","options":["„Ich habe das Gefühl, dass dieses Gespräch nicht mehr produktiv ist, weil wir nicht mehr über die Sache, sondern übereinander reden. Ich möchte es hier beenden.“","„Mit dir kann man nicht reden, du bist offenbar unbelehrbar und hörst nur dir selbst zu. Ich bin raus und rede nicht mehr mit dir.“","„Okay, du hast gewonnen. Sag mir einfach, was ich glauben soll, dann haben wir endlich Ruhe und können das Thema abhaken.“","„Ich antworte dir erst wieder, wenn du dich für deinen Ton entschuldigt und alle deine Punkte ausdrücklich zurückgenommen hast.“"],"correctIndex":0,"explanation":"Ein Gespräch lohnt sich nur, solange beide Seiten sich auf die Sache einlassen; hier geht die andere Seite auf keinen deiner Punkte ein, und zwei Versuche, zur Sache zurückzukehren, sind gescheitert. Der beste Abschlusssatz bleibt ruhig, benennt sachlich den Grund (ihr redet nicht mehr über die Sache, sondern übereinander) und beendet das Gespräch, ohne die Person abzuwerten. „Mit dir kann man nicht reden“ greift dagegen die Person an und wirkt leicht wie ein Verlust der Fassung. „Du hast gewonnen“ gibt nach, ohne den Grund zu nennen, und die Forderung nach einer Entschuldigung knüpft das Ende an eine Bedingung, statt das Gespräch selbst zu beenden.","coreRule":"⚡ Steige ruhig, bestimmt und begründet aus: Benenne sachlich den Grund, ohne die Person abzuwerten.","beleg":"Werkstück H.2.4 (Wie man den Ausstieg vollzieht: Meta-Kommunikation)","status":"entwurf","kurz":"Wenn zwei Beruhigungsversuche gescheitert sind und nichts mehr geklärt wird, lohnt weiteres Antworten nicht. Ein guter Abschluss benennt ruhig den Grund und beendet das Gespräch, ohne die Person abzuwerten oder an Bedingungen zu knüpfen.","prueffrage":"Ist das Gespräch nach deinem letzten Satz wirklich beendet, und was erfährt dein Gegenüber darin über den Grund?","rueckmeldung":[{"option":1,"text":"Das Gespräch zu beenden ist vernünftig, und er geht tatsächlich auf keinen deiner Punkte ein. Der Satz wertet aber die Person ab, statt den Grund zu nennen, und ein solcher Abgang wirkt schnell wie ein Verlust der Fassung."},{"option":2,"text":"Der Wunsch nach Ruhe ist verständlich, denn jede Antwort kostet Kraft. Nachgeben benennt aber weder den Grund noch beendet es das Gespräch klar: Du tust so, als sei die Sache entschieden, obwohl du es nicht so meinst."},{"option":3,"text":"Der Ärger über den Ton ist berechtigt. Der Satz beendet das Gespräch aber nicht, sondern knüpft es an eine Forderung, und ob sie erfüllt wird, liegt dann beim Gegenüber, das bisher nicht auf die Sache eingeht."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Rogers, Howieson & Neame (2018): I understand you feel that way, but I feel this way: the benefits of I-language and communicating perspective during conflict. PeerJ 6:e4831","oeffentlich":true,"doi":"10.7717/peerj.4831","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5961625/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansen, H. (2015/2024): Fallacies. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-047","clusterId":"H","werkstueckRef":"H.2.4","stufe":3,"question":"Ein Gespräch über Wohnungspolitik läuft seit einer Stunde. Du hast zweimal ruhig angeboten, zur Sachfrage zurückzukehren. Welche Beobachtung rechtfertigt es am ehesten, das Gespräch jetzt zu beenden?","options":["Er widerspricht dir hartnäckig, bleibt dabei aber sachlich, und dein Argument gerät allmählich unter Druck.","Er hat einmal einen Strohmann benutzt, sich sofort entschuldigt und ist danach auf deinen Einwand sachlich eingegangen.","Dir fehlen gerade die Gegenargumente, und du möchtest das Gespräch beenden, bevor es für dich unangenehm wird.","Er greift dich fortlaufend persönlich an, und deine mehrfachen Versuche, zur Sachebene zurückzukehren, scheitern."],"correctIndex":3,"explanation":"Ein Abbruch ist dann begründet, wenn das Gegenüber nicht mehr nach den Regeln des ehrlichen Diskurses spielt: Unehrliche Mittel wie persönliche Angriffe sind nicht mehr vereinzelte Ausrutscher, sondern die primäre Kommunikationsstrategie, und mehrfache Versuche, das Gespräch auf die sachliche Ebene zurückzuführen, scheitern. Dann ist das Spiel manipuliert, und jeder weitere Beitrag kostet mentale Energie, ohne dass ein echter Austausch von Ideen möglich ist. Sachlicher Widerspruch ist dagegen der Normalfall eines guten Gesprächs, auch wenn er unbequem ist. Ein einzelner Fehler, der sofort korrigiert wird, zeigt gerade Redlichkeit, denn dort ist der Einzelfall kein Dauerzustand. Und eigenes Unbehagen oder fehlende Gegenargumente sind kein Ausstiegsgrund: Ein Ausstieg setzt voraus, dass das Gegenüber systematisch unehrliche Taktiken einsetzt, und nicht, dass das Gespräch für dich selbst schwierig wird.","coreRule":"⚡ Ein Gespräch zu verlassen ist angemessen bei systematischer Unehrlichkeit und gescheiterten Rückführungsversuchen, nicht bei bloßem Unbehagen oder Gegenwind.","beleg":"Werkstück H.2.4 (Anwendung & Relevanz: Wann man den Tisch verlässt; Red Flags)","status":"entwurf","scenario":"Dein Gesprächspartner antwortet auf keinen deiner Punkte inhaltlich. Stattdessen wertet er dich bei jedem Beitrag persönlich ab („Typisch du, du hast ja keine Ahnung“). Deine zwei freundlichen Rückführungen auf die Sache hat er jeweils mit neuen Angriffen beantwortet.","kurz":"Wer dich bei jedem Beitrag persönlich angreift und zweimal auf Rückführungen zur Sache mit neuen Angriffen reagiert, spielt nicht mehr ehrlich. Der Fehler wäre, schon bei Gegenwind oder eigenem Unbehagen auszusteigen, statt auf ein systematisches Muster zu achten.","prueffrage":"Woran erkennst du im Gesprächsverlauf, ob jemand dir nur widerspricht oder ob er gar nicht mehr über die Sache redet?","rueckmeldung":[{"option":0,"text":"Wer hartnäckig widerspricht und dich unter Druck setzt, macht ein Gespräch anstrengend, aber nicht unredlich. Sachlicher Widerspruch gehört zum Normalfall eines guten Gesprächs, auch wenn er unbequem ist, und ist für sich noch kein Grund aufzuhören."},{"option":1,"text":"Ein Strohmann ist ein unfairer Zug, hier aber ein einzelner Ausrutscher. Er wurde sofort zurückgenommen, und danach ging er auf deinen Einwand ein. Das spricht für Redlichkeit, nicht für ein manipuliertes Gespräch."},{"option":2,"text":"Fehlende Gegenargumente sind unangenehm, sagen aber nichts über das Verhalten des anderen. Ein Abbruch ist begründet, wenn das Gegenüber systematisch unehrlich vorgeht, nicht schon, wenn das Gespräch für dich selbst schwierig wird."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansen, H. (2015/2024): Fallacies. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-h-048","clusterId":"H","werkstueckRef":"H.2.4","stufe":4,"question":"Was ist an dieser Antwort deines Cousins das eigentliche Problem für ein sinnvolles Gespräch?","scenario":"Dein Cousin antwortet auf jeden Beleg: „Genau das sagen sie ja, damit wir es nicht merken. Dein Beleg ist Teil der Vertuschung.“","options":["Er wirft dir Vertuschung vor, und jeder Verdacht auf Vertuschung macht ein Gespräch gefährlich.","Er wertet jeden Gegenbeweis als Teil der Verschwörung, sodass nichts ihn mehr widerlegen könnte.","Er bleibt bei seiner Meinung, und wer trotz Belegen nicht nachgibt, spielt unehrlich.","Er klingt unfreundlich, und Unfreundlichkeit allein genügt, um jedes Gespräch zu beenden."],"correctIndex":1,"explanation":"Eine Behauptung, die jeden Gegenbeweis als Beweis für die Verschwörung umdeutet, lässt sich durch nichts mehr widerlegen. Dann ist kein echter Austausch von Ideen mehr möglich: Weitere Belege kosten dich nur Zeit und Energie. Ein ruhiger, begründeter Ausstieg („Wir kommen hier nicht weiter, lass uns das Thema beenden.“) ist dann die vernünftigere Wahl, als weiter zu argumentieren.","coreRule":"⚡ Wo jeder Beleg zum Beweis für die Verschwörung wird, ist das Spiel versiegelt: Dann hilft nur der ruhige Ausstieg.","beleg":"Werkstück H.2.4 (Anwendung & Relevanz: ‚Wenn der Verschwörungsmythos sich versiegelt‘)","status":"entwurf","kurz":"Wenn jeder Beleg zum Teil der Verschwörung erklärt wird, kann nichts mehr widerlegen, was dein Cousin behauptet. Dann kostet weiteres Belegen nur Kraft, und ein ruhiger Ausstieg ist sinnvoller als noch ein Argument.","prueffrage":"Was hat dein Cousin auf deine bisherigen Belege geantwortet, und hing seine Antwort davon ab, was im jeweiligen Beleg stand?","rueckmeldung":[{"option":0,"text":"Ein Vorwurf der Vertuschung kann durchaus berechtigt und prüfbar sein, und gefährlich macht er ein Gespräch nicht von selbst. Entscheidend ist hier, dass jeder Beleg als Teil der Vertuschung gilt und damit nichts mehr widerlegen kann."},{"option":2,"text":"Bei einer Meinung zu bleiben ist an sich nicht unehrlich, denn Ansichten ändern sich oft langsam. Das Problem liegt woanders: Sein Argument ist so gebaut, dass kein denkbarer Beleg es mehr treffen könnte."},{"option":3,"text":"Der Ton kann ein Gespräch belasten, aber allein deshalb endet es nicht zwangsläufig. Der Grund für den Ausstieg liegt im Aufbau seines Arguments: Es erklärt jeden Gegenbeleg zum Beweis für die eigene Behauptung."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky & Cook (2020): The Conspiracy Theory Handbook (Skeptical Science)","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben"}]`);export{t as n,n as t};